function renderRoleSelectorTabs() {
    const container = document.getElementById('roleSelectorTabsContainer');
    if (!container) return;

    normalizeRolesConfig();

    container.innerHTML = (STATE.rolesConfig || []).map(r => {
        const isSelected = (r.key === _selectedRoleKeyForEditing);
        const color = r.color || '#0284c7';
        return `
            <button type="button" onclick="selectRoleForEditing('${r.key}')" style="background:${isSelected ? color : '#ffffff'}; color:${isSelected ? '#ffffff' : '#334155'}; border:2px solid ${color}; border-radius:8px; padding:7px 16px; font-weight:800; font-size:0.86rem; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:${isSelected ? '0 4px 6px -1px rgba(0,0,0,0.15)' : 'none'}; transition:all 0.15s ease;">
                <span style="width:10px; height:10px; border-radius:50%; background:${isSelected ? '#ffffff' : color};"></span>
                ${r.name}
            </button>
        `;
    }).join('');
}
window.renderRoleSelectorTabs = renderRoleSelectorTabs;

function selectRoleForEditing(roleKey) {
    _selectedRoleKeyForEditing = roleKey;
    renderRoleSelectorTabs();
    loadRoleIntoPermissionsPanel(roleKey);
}
window.selectRoleForEditing = selectRoleForEditing;

function initNewRoleForm() {
    _selectedRoleKeyForEditing = 'nuevo';
    renderRoleSelectorTabs();

    const keyInput = document.getElementById('activeRoleKey');
    const nameInput = document.getElementById('activeRoleName');
    const descInput = document.getElementById('activeRoleDesc');
    const colorInput = document.getElementById('activeRoleColor');

    if (keyInput) { keyInput.value = ''; keyInput.readOnly = false; keyInput.focus(); }
    if (nameInput) nameInput.value = '';
    if (descInput) descInput.value = '';
    if (colorInput) colorInput.value = '#0284c7';

    renderActiveRolePermissionsGrid(['dashboard']);
    showToast('Complete los datos del nuevo rol y active qué módulos podrá ver.', 'info');
}
window.initNewRoleForm = initNewRoleForm;

function loadRoleIntoPermissionsPanel(roleKey) {
    normalizeRolesConfig();
    const r = (STATE.rolesConfig || []).find(x => x.key === roleKey) || STATE.rolesConfig[0];
    if (!r) return;

    _selectedRoleKeyForEditing = r.key;

    const keyInput = document.getElementById('activeRoleKey');
    const nameInput = document.getElementById('activeRoleName');
    const descInput = document.getElementById('activeRoleDesc');
    const colorInput = document.getElementById('activeRoleColor');

    const isSystemRole = (r.isSystem || ['admin','director','secretaria','profesor_auxiliar','docente'].includes(r.key));

    if (keyInput) { keyInput.value = r.key; keyInput.readOnly = isSystemRole; }
    if (nameInput) nameInput.value = r.name;
    if (descInput) descInput.value = r.description || '';
    if (colorInput) colorInput.value = r.color || '#0284c7';

    renderActiveRolePermissionsGrid(r.permissions || []);

    const delBtn = document.getElementById('btnDeleteActiveRole');
    if (delBtn) {
        if (r.key === 'admin') {
            delBtn.style.display = 'none';
        } else {
            delBtn.style.display = 'inline-flex';
            delBtn.setAttribute('onclick', `deleteRole('${r.key}')`);
        }
    }
}
window.loadRoleIntoPermissionsPanel = loadRoleIntoPermissionsPanel;



async function saveActiveRolePermissions() {
    if (STATE.currentRole !== 'admin' && STATE.currentUser?.role !== 'admin') {
        showToast('Solo el Super Administrador del Sistema puede guardar roles y permisos.', 'warning');
        return;
    }

    const keyInput = document.getElementById('activeRoleKey');
    const nameInput = document.getElementById('activeRoleName');
    const descInput = document.getElementById('activeRoleDesc');
    const colorInput = document.getElementById('activeRoleColor');

    const key = keyInput ? keyInput.value.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_') : '';
    const name = nameInput ? nameInput.value.trim() : '';
    const desc = descInput ? descInput.value.trim() : '';
    const color = colorInput ? colorInput.value : '#0284c7';

    if (!key || !name) {
        showToast('Debe ingresar la clave y el nombre del rol.', 'warning');
        return;
    }

    const permissionLevels = {};
    const permissions = [];

    SYSTEM_MODULES_LIST.forEach(mod => {
        if (key === 'admin') {
            permissionLevels[mod.key] = 'edit';
            permissions.push(mod.key, mod.key + '_edit', mod.key + '_view');
        } else {
            const checkedRadio = document.querySelector(`input[name="permLevel_${mod.key}"]:checked`);
            const level = checkedRadio ? checkedRadio.value : 'none';
            permissionLevels[mod.key] = level;

            if (level === 'edit') {
                permissions.push(mod.key, mod.key + '_edit', mod.key + '_view');
            } else if (level === 'view') {
                permissions.push(mod.key, mod.key + '_view');
            }
        }
    });

    normalizeRolesConfig();

    try {
        const existingIdx = STATE.rolesConfig.findIndex(r => r.key === key);
        if (existingIdx !== -1) {
            STATE.rolesConfig[existingIdx].name = name;
            STATE.rolesConfig[existingIdx].description = desc;
            STATE.rolesConfig[existingIdx].color = color;
            STATE.rolesConfig[existingIdx].permissions = permissions;
            STATE.rolesConfig[existingIdx].permissionLevels = permissionLevels;
        } else {
            STATE.rolesConfig.push({
                key: key,
                name: name,
                description: desc,
                color: color,
                isSystem: false,
                permissions: permissions,
                permissionLevels: permissionLevels
            });
        }
        _selectedRoleKeyForEditing = key;

        // CONFIRMACIÓN DE ESCRITURA ATÓMICA EN FIREBASE (AISLAMIENTO TOTAL DE ROLES)
        const nowTime = Date.now();
        const roleObj = {
            key: key,
            name: name,
            description: desc,
            color: color,
            permissions: permissions,
            permissionLevels: permissionLevels,
            lastModified: nowTime
        };

        // 🌟 A. Persistencia Atómica en Google Cloud Firestore (updateDoc con fallback merge: true y withTimeout)
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
                const rolRef = doc(db, 'roles', key);
                const roleDocRef = doc(db, 'rolesConfig', key);
                const configDocRef = doc(db, 'config', 'rolesConfig');

                // Actualizar documento individual del rol sin tocar otros datos
                if (typeof updateDoc === 'function') {
                    try {
                        await withTimeout(updateDoc(roleDocRef, roleObj), 6000);
                    } catch(updErr) {
                        if (typeof setDoc === 'function') {
                            await withTimeout(setDoc(roleDocRef, roleObj, { merge: true }), 6000);
                        }
                    }
                } else if (typeof setDoc === 'function') {
                    await withTimeout(setDoc(roleDocRef, roleObj, { merge: true }), 6000);
                }

                // Sincronizar documento en colección roles/ con merge: true
                if (typeof setDoc === 'function') {
                    await withTimeout(setDoc(rolRef, {
                        id: key,
                        key: key,
                        nombre: name,
                        name: name,
                        descripcion: desc,
                        description: desc,
                        color: color,
                        permisos: permissions,
                        permissions: permissions,
                        ultimaModificacion: new Date().toISOString(),
                        lastModified: nowTime
                    }, { merge: true }), 6000).catch(() => null);
                }

                // Actualizar catálogo institucional de roles con merge: true
                if (typeof updateDoc === 'function') {
                    try {
                        await withTimeout(updateDoc(configDocRef, { list: STATE.rolesConfig, lastModified: nowTime }), 6000);
                    } catch(updErr) {
                        if (typeof setDoc === 'function') {
                            await withTimeout(setDoc(configDocRef, { list: STATE.rolesConfig, lastModified: nowTime }, { merge: true }), 6000);
                        }
                    }
                } else if (typeof setDoc === 'function') {
                    await withTimeout(setDoc(configDocRef, { list: STATE.rolesConfig, lastModified: nowTime }, { merge: true }), 6000);
                }
                console.log(`🔥 [Firestore] Rol "${key}" actualizado atómicamente con updateDoc/merge.`);
            } catch(fsErr) {
                console.warn("Aviso al persistir roles en Firestore:", fsErr);
            }
        }

        // 🌟 B. Persistencia Atómica y Aislada en Firebase Realtime Database con withTimeout
        let ok = false;
        try {
            const rtdbPromises = [];
            if (typeof EnccoCloudSync !== 'undefined') {
                if (typeof EnccoCloudSync.patchNode === 'function') {
                    rtdbPromises.push(EnccoCloudSync.patchNode(`roles/${key}`, roleObj));
                }
                if (typeof EnccoCloudSync.syncNode === 'function') {
                    rtdbPromises.push(EnccoCloudSync.syncNode('rolesConfig', STATE.rolesConfig));
                }
            }

            if (rtdbPromises.length > 0) {
                const results = await withTimeout(Promise.all(rtdbPromises), 6000, 'Tiempo de espera en Realtime Database agotado.');
                ok = results.every(Boolean);
            } else {
                const fUrl = (typeof getFirebaseDatabaseUrl === 'function') ? getFirebaseDatabaseUrl() : null;
                if (fUrl) {
                    const controller = new AbortController();
                    const fetchTimeout = setTimeout(() => controller.abort(), 5000);
                    try {
                        const res = await fetch(`${fUrl}/encc_school_state/rolesConfig.json`, {
                            method: 'PUT',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(STATE.rolesConfig),
                            signal: controller.signal
                        });
                        clearTimeout(fetchTimeout);
                        ok = res.ok;
                    } catch(e) {
                        clearTimeout(fetchTimeout);
                        ok = false;
                    }
                } else {
                    ok = true;
                }
            }
        } catch(rtdbErr) {
            console.warn("Aviso en RTDB al guardar rol activo:", rtdbErr);
        }

        if (!ok) {
            console.warn("RTDB no confirmó inmediatamente, manteniendo persistencia local y en Firestore.");
        }

        saveStateToLocalStorage();
        applyUserRole(STATE.currentRole);
        renderRolesManagementView();
        showToast(`Permisos del rol "${name}" confirmados en Firebase.`, 'success');
    } catch(err) {
        console.error("❌ Error al guardar roles en Firebase:", err);
        showToast(`Error al guardar roles en Firebase: ${err.message || err}`, 'danger');
    }
}
window.saveActiveRolePermissions = saveActiveRolePermissions;


