// ======================================================================
//    MOTOR OFICIAL EXCLUSIVO: GOOGLE FIREBASE REALTIME DATABASE 2026
// ======================================================================

const FIREBASE_CONFIG = {
    defaultUrl: "https://encco-jutiapa-live-2026-default-rtdb.firebaseio.com",
    storageKey: "ENCCO_FIREBASE_URL"
};



// Descargar de Firebase Realtime Database (GET)
async function pullStateFromFirebaseCloud(force = false) {
    const firebaseUrl = getFirebaseDatabaseUrl();
    if (!firebaseUrl) return false;

    const endpoint = `${firebaseUrl}/encc_school_state.json`;

    try {
        const response = await fetch(endpoint);
        if (response.ok) {
            const cloudState = await response.json();
            if (cloudState && typeof cloudState === 'object' && (cloudState.students || cloudState.users)) {
                const applied = applyIncomingCloudState(cloudState, force);
                if (applied) {
                    updateDbSyncStatus('synced');

                    return true;
                }
            }
        }
    } catch(err) {
        console.warn("Aviso al consultar Base de Datos Nube:", err);
    }
    return false;
}
window.pullStateFromFirebaseCloud = pullStateFromFirebaseCloud;

// Redirección de llamadas heredadas a Firebase
function autoSyncToCloud(isPush = true, showNotification = false) {
    if (isPush) {
        return pushStateToFirebaseCloud(showNotification);
    } else {
        return pullStateFromFirebaseCloud(false);
    }
}
window.autoSyncToCloud = autoSyncToCloud;

function autoSyncToFirebase(isPush = true, showNotification = false) {
    return autoSyncToCloud(isPush, showNotification);
}
window.autoSyncToFirebase = autoSyncToFirebase;

function syncStateToFirebaseImmediate(showNotification = false) {
    return pushStateToFirebaseCloud(showNotification);
}
window.syncStateToFirebaseImmediate = syncStateToFirebaseImmediate;

let _firebaseEventSource = null;

// ⚡ [v185] Bandera global que bloquea applyIncomingCloudState durante operaciones de guardado
let _isSavingLocally = false;
let _isSavingLocallyTimeout = null;

// ⚡ [v186] Control de reconexión SSE automática para móvil
let _sseReconnectTimeout = null;
let _visibilityReconnecting = false;

function initFirebaseRealtimeConnection() {
    const firebaseUrl = getFirebaseDatabaseUrl();

    // Estado online inmediato por defecto si el navegador tiene conectividad
    if (typeof navigator === 'undefined' || navigator.onLine !== false) {
        updateDbSyncStatus('synced');
    } else {
        updateDbSyncStatus('disconnected');
    }

    if (!firebaseUrl) {
        updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
        return;
    }

    // Escuchadores de eventos de conectividad de red del navegador
    if (typeof window !== 'undefined' && !window._hasNetworkSyncListeners) {
        window._hasNetworkSyncListeners = true;
        window.addEventListener('online', () => {
            console.log("🌐 [Red] Conexión a Internet detectada.");
            updateDbSyncStatus('synced');
            pullStateFromFirebaseCloud(false);
            if (typeof triggerInstantCloudPush === 'function') triggerInstantCloudPush();
        });
        window.addEventListener('offline', () => {
            console.warn("⚠️ [Red] Sin conexión a Internet.");
            updateDbSyncStatus('disconnected');
        });
    }

    // 1. Escuchar cambios en tiempo real vía Server-Sent Events (SSE de Firebase RTDB)
    if (typeof EventSource !== 'undefined') {
        try {
            if (_firebaseEventSource) {
                _firebaseEventSource.close();
                _firebaseEventSource = null;
            }
            const sseUrl = `${firebaseUrl}/encc_school_state.json`;
            _firebaseEventSource = new EventSource(sseUrl);

            // Registrar efecto de limpieza en AuthStore para destrucción garantizada en logout
            if (window.EnccoAuthStore && typeof window.EnccoAuthStore.registerEffect === 'function') {
                window.EnccoAuthStore.registerEffect(() => {
                    if (_firebaseEventSource) {
                        try {
                            _firebaseEventSource.close();
                            _firebaseEventSource = null;
                            console.log("🔒 [Cleanup Effect] Firebase EventSource cerrado.");
        } catch(e) {}
                    }
                });
            }
            _firebaseEventSource.addEventListener('put', (e) => {
                try {
                    const parsed = JSON.parse(e.data);
                    if (!parsed) return;
                    const rawPath = parsed.path || '/';
                    const nodeData = parsed.data;
                    const cleanPath = rawPath.replace(/^\/+/, '');

                    // [v190] Sincronización continua y reactiva de eventos SSE de Firebase

                    if (cleanPath === '' || cleanPath === '/') {
                        if (nodeData && typeof nodeData === 'object') {
                            const sseTime = Number(nodeData.lastModified) || 0;
                            const myLastSave = Math.max(Number(STATE._lastSavedLocally) || 0, Number(STATE.lastModified) || 0);
                            if (sseTime <= myLastSave && myLastSave > 0) {
                                // Eco propio o reconexión SSE con datos no más nuevos que los locales
                                console.log(`🛡️ [SSE Anti-Reversión] Evento raíz ignorado (sseTime: ${sseTime} <= local: ${myLastSave})`);
                            } else {
                                applyIncomingCloudState(nodeData, false);
                            }
                        }
                    } else if (cleanPath === 'pensum') {
                        if (Array.isArray(nodeData)) {
                            STATE.pensum = nodeData;
                            if (typeof syncPensumTeachersWithUsers === 'function') syncPensumTeachersWithUsers(false);
                            // SINCRONIZACIÓN BIDIRECCIONAL EN TIEMPO REAL:
                            // Si se asigna o quita un docente en clases, actualizar editor de pensum inmediatamente sin recargar
                            if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                            if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
                            if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
                            if (typeof updateAssignmentSelects === 'function') updateAssignmentSelects();
                            if (typeof populatePensumTeacherSelect === 'function') populatePensumTeacherSelect();
                            if (typeof renderCurrentView === 'function' && (STATE.activeView === 'class-assignments' || STATE.activeView === 'pensum')) renderCurrentView();
                        }
                    } else if (cleanPath === 'pensumCatalog') {
                        if (Array.isArray(nodeData)) {
                            STATE.pensumCatalog = nodeData;
                            // Si se modifica el pensum, reflejar en asignación de docentes y selects en tiempo real
                            if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
                            if (typeof updatePensumCatalogSelects === 'function') updatePensumCatalogSelects();
                            if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();
                            if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                            if (typeof renderCurrentView === 'function' && (STATE.activeView === 'pensum' || STATE.activeView === 'class-assignments')) renderCurrentView();
                        }
                    } else if (cleanPath === 'users') {
                        if (Array.isArray(nodeData) && nodeData.length > 0) {
                            STATE.users = nodeData;
                            if (typeof syncPensumTeachersWithUsers === 'function') syncPensumTeachersWithUsers(true);

                            // ⚡ Sincronización reactiva del usuario activo si su rol o perfil cambió en la nube
                            if (STATE.currentUser && Array.isArray(nodeData)) {
                                const myUpdated = nodeData.find(u => u.id === STATE.currentUser.id || u.username === STATE.currentUser.username);
                                if (myUpdated) {
                                    const oldRole = STATE.currentRole;
                                    STATE.currentUser = { ...STATE.currentUser, ...myUpdated };
                                    if (myUpdated.role && myUpdated.role !== oldRole) {
                                        STATE.currentRole = myUpdated.role;
                                        if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole);
                                    }
                                }
                            }

                            if (typeof renderUsersTable === 'function') renderUsersTable();
                            if (typeof updateTopRoleBar === 'function') updateTopRoleBar();
                            if (typeof updateLoginAccountSelect === 'function') updateLoginAccountSelect();
                            if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();
                            if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                            if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
                            if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
                            if (typeof renderCurrentView === 'function' && STATE.activeView === 'users') renderCurrentView();
                        }
                    } else if (cleanPath.startsWith('users/')) {
                        const parts = cleanPath.split('/');
                        const uIdx = parseInt(parts[1]);
                        if (!isNaN(uIdx) && Array.isArray(STATE.users) && STATE.users[uIdx]) {
                            STATE.users[uIdx] = { ...STATE.users[uIdx], ...(typeof nodeData === 'object' ? nodeData : {}) };
                            if (STATE.currentUser && STATE.currentUser.id === STATE.users[uIdx].id) {
                                const oldR = STATE.currentRole;
                                STATE.currentUser = { ...STATE.currentUser, ...STATE.users[uIdx] };
                                if (STATE.users[uIdx].role && STATE.users[uIdx].role !== oldR) {
                                    STATE.currentRole = STATE.users[uIdx].role;
                                    if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole);
                                }
                            }
                            if (typeof renderUsersTable === 'function') renderUsersTable();
                            if (typeof updateTopRoleBar === 'function') updateTopRoleBar();
                        }
                    } else if (cleanPath === 'gradesList') {
                        if (Array.isArray(nodeData)) {
                            STATE.gradesList = nodeData;
                            if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                            if (typeof renderGradesTable === 'function') renderGradesTable();
                            if (typeof updateGradeSelects === 'function') updateGradeSelects();
                            if (typeof renderCurrentView === 'function' && (STATE.activeView === 'grades' || STATE.activeView === 'guide-teachers')) renderCurrentView();
                        }
                    } else if (cleanPath.startsWith('gradesList/')) {
                        const parts = cleanPath.split('/');
                        const gIdx = parseInt(parts[1]);
                        if (!isNaN(gIdx) && Array.isArray(STATE.gradesList) && STATE.gradesList[gIdx]) {
                            STATE.gradesList[gIdx] = { ...STATE.gradesList[gIdx], ...(typeof nodeData === 'object' ? nodeData : {}) };
                            if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                            if (typeof renderGradesTable === 'function') renderGradesTable();
                            if (typeof updateGradeSelects === 'function') updateGradeSelects();
                        }
                    } else if (cleanPath === 'secciones' || cleanPath === 'secciones.json') {
                        if (nodeData && typeof nodeData === 'object') {
                            Object.entries(nodeData).forEach(([docKey, sec]) => {
                                if (sec) {
                                    const gId = sec.gradoId || (docKey.split('_')[0]);
                                    const sId = sec.seccionId || (docKey.split('_')[1]);
                                    const targetGrade = (STATE.gradesList || []).find(g => 
                                        (g && g.id === sec.id) || 
                                        (g && g.code && g.code.includes(gId) && g.code.includes(sId)) ||
                                        (g && g.name && g.name.includes(gId) && g.section && g.section.includes(sId))
                                    );
                                    if (targetGrade) {
                                        targetGrade.guideTeacherId = sec.maestroGuiaId || null;
                                        targetGrade.guideTeacher = sec.maestroGuiaNombre || 'Sin asignar';
                                    }
                                }
                            });
                            if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                            if (typeof renderGradesTable === 'function') renderGradesTable();
                        }
                    } else if (cleanPath.startsWith('secciones/')) {
                        const secKey = cleanPath.split('/')[1];
                        if (secKey && nodeData && typeof nodeData === 'object') {
                            const parts = secKey.split('_');
                            const gId = nodeData.gradoId || parts[0];
                            const sId = nodeData.seccionId || parts[1];
                            const targetGrade = (STATE.gradesList || []).find(g => 
                                (g && g.code && g.code.includes(gId) && g.code.includes(sId)) ||
                                (g && g.name && g.name.includes(gId) && g.section && g.section.includes(sId))
                            );
                            if (targetGrade) {
                                targetGrade.guideTeacherId = nodeData.maestroGuiaId || null;
                                targetGrade.guideTeacher = nodeData.maestroGuiaNombre || 'Sin asignar';
                                if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                                if (typeof renderGradesTable === 'function') renderGradesTable();
                            }
                        }
                    } else if (cleanPath === 'students') {
                        if (Array.isArray(nodeData)) {
                            if (!window._rtdbStudentIndexMap) window._rtdbStudentIndexMap = new Map();
                            if (!window._rtdbIndexToIdMap) window._rtdbIndexToIdMap = new Map();
                            nodeData.forEach((st, idx) => {
                                if (st && st.id) {
                                    window._rtdbStudentIndexMap.set(st.id, idx);
                                    window._rtdbIndexToIdMap.set(idx, st.id);
                                    if (st.personalCode) window._rtdbStudentIndexMap.set(st.personalCode, idx);
                                    if (st.carne) window._rtdbStudentIndexMap.set(st.carne, idx);
                                }
                            });
                            if (Array.isArray(STATE.students) && STATE.students.length > 0) {
                                const localDirty = window._locallyDirtyStudentIds || new Set();
                                const studentMap = new Map();
                                STATE.students.forEach(st => studentMap.set(st.id || st.personalCode, st));

                                nodeData.forEach(incSt => {
                                    const key = incSt.id || incSt.personalCode;
                                    const localSt = studentMap.get(key);
                                    if (!localSt) {
                                        studentMap.set(key, incSt);
                                    } else if (!localDirty.has(key)) {
                                        const mergedGrades = { ...(localSt.grades || {}), ...(incSt.grades || {}) };
                                        const mergedDetails = { ...(localSt.gradebookDetails || {}) };
                                        if (incSt.gradebookDetails) {
                                            Object.keys(incSt.gradebookDetails).forEach(subj => {
                                                mergedDetails[subj] = {
                                                    ...(mergedDetails[subj] || {}),
                                                    ...(incSt.gradebookDetails[subj] || {})
                                                };
                                            });
                                        }
                                        Object.assign(localSt, incSt, {
                                            grades: mergedGrades,
                                            gradebookDetails: mergedDetails
                                        });
                                    }
                                });
                            } else {
                                STATE.students = nodeData;
                            }
                            if (typeof renderGradebookTable === 'function') renderGradebookTable();
                            if (typeof renderStudentsTable === 'function') renderStudentsTable();
                            if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
                        }
                    } else if (cleanPath.startsWith('students/')) {
                        const subParts = cleanPath.split('/');
                        const rtdbIdx = parseInt(subParts[1]);
                        if (!isNaN(rtdbIdx)) {
                            let targetStudent = null;
                            if (window._rtdbIndexToIdMap && window._rtdbIndexToIdMap.has(rtdbIdx)) {
                                const stId = window._rtdbIndexToIdMap.get(rtdbIdx);
                                targetStudent = (STATE.students || []).find(s => s.id === stId);
                            }
                            if (!targetStudent && Array.isArray(STATE.students) && STATE.students[rtdbIdx]) {
                                targetStudent = STATE.students[rtdbIdx];
                            }

                            if (targetStudent) {
                                if (window._locallyDirtyStudentIds && window._locallyDirtyStudentIds.has(targetStudent.id)) {
                                    return;
                                }
                                if (subParts.length === 2) {
                                    if (nodeData && typeof nodeData === 'object') {
                                        Object.assign(targetStudent, nodeData);
                                    }
                                } else if (subParts[2] === 'grades') {
                                    if (subParts.length === 3) {
                                        targetStudent.grades = { ...(targetStudent.grades || {}), ...(nodeData || {}) };
                                    } else if (subParts.length >= 4) {
                                        const subj = decodeURIComponent(subParts[3]);
                                        if (!targetStudent.grades) targetStudent.grades = {};
                                        targetStudent.grades[subj] = nodeData;
                                    }
                                } else if (subParts[2] === 'gradebookDetails') {
                                    if (subParts.length === 3) {
                                        targetStudent.gradebookDetails = { ...(targetStudent.gradebookDetails || {}), ...(nodeData || {}) };
                                    } else if (subParts.length === 4) {
                                        const subj = decodeURIComponent(subParts[3]);
                                        if (!targetStudent.gradebookDetails) targetStudent.gradebookDetails = {};
                                        targetStudent.gradebookDetails[subj] = { ...(targetStudent.gradebookDetails[subj] || {}), ...(nodeData || {}) };
                                    } else if (subParts.length >= 5) {
                                        const subj = decodeURIComponent(subParts[3]);
                                        const unitStr = subParts[4];
                                        if (!targetStudent.gradebookDetails) targetStudent.gradebookDetails = {};
                                        if (!targetStudent.gradebookDetails[subj]) targetStudent.gradebookDetails[subj] = {};
                                        targetStudent.gradebookDetails[subj][unitStr] = nodeData;
                                    }
                                }
                                if (typeof renderGradebookTable === 'function') renderGradebookTable();
                                if (typeof renderStudentsTable === 'function') renderStudentsTable();
                                if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
                            }
                        }
                    } else if (cleanPath === 'attendanceRecords') {
                        if (nodeData && typeof nodeData === 'object') {
                            STATE.attendanceRecords = nodeData;
                            if (typeof renderAttendanceTable === 'function') renderAttendanceTable();
                        }
                    } else if (cleanPath === 'disciplineReports') {
                        if (Array.isArray(nodeData)) {
                            STATE.disciplineReports = nodeData;
                            if (typeof renderDisciplineTable === 'function') renderDisciplineTable();
                        }
                    } else if (cleanPath === 'rolesConfig') {
                        if (Array.isArray(nodeData)) {
                            STATE.rolesConfig = nodeData;
                            if (typeof renderRolesTable === 'function') renderRolesTable();
                            if (typeof renderRoleSelectorTabs === 'function') renderRoleSelectorTabs();
                        }
                    } else if (cleanPath === 'cycles') {
                        if (Array.isArray(nodeData)) {
                            STATE.cycles = nodeData;
                            if (typeof updateCycleSelects === 'function') updateCycleSelects();
                        }
                    } else if (cleanPath === 'careers') {
                        if (Array.isArray(nodeData)) {
                            STATE.careers = nodeData;
                            if (typeof updateCareerSelects === 'function') updateCareerSelects();
                        }
                    } else if (cleanPath === 'activeCycle') {
                        STATE.activeCycle = nodeData;
                        if (typeof updateCycleSelects === 'function') updateCycleSelects();
                    } else if (cleanPath === 'config') {
                        if (nodeData && typeof nodeData === 'object') {
                            STATE.config = nodeData;
                        }
                    }
                    updateDbSyncStatus('synced');
                } catch(err) {
                    console.warn("Aviso en SSE put listener:", err);
                }
            });
            _firebaseEventSource.addEventListener('patch', (e) => {
                try {
                    const data = JSON.parse(e.data);
                    if (data && data.data && typeof data.data === 'object') {
                        if (data.path === '/' || !data.path) {
                            applyIncomingCloudState(data.data, false);
                        } else if (typeof pullStateFromFirebaseCloud === 'function') {
                            pullStateFromFirebaseCloud(false);
                        }
                    }
                    updateDbSyncStatus('synced');
                } catch(err) {}
            });
            _firebaseEventSource.onerror = () => {
                // ⚡ [v186] Reconexión automática SSE para móvil
                if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                    updateDbSyncStatus('disconnected');
                    return;
                }
                // Si estamos online pero SSE falló, intentar reconexión automática
                updateDbSyncStatus('disconnected');
                if (_sseReconnectTimeout) clearTimeout(_sseReconnectTimeout);
                _sseReconnectTimeout = setTimeout(() => {
                    _sseReconnectTimeout = null;
                    if (typeof navigator === 'undefined' || navigator.onLine !== false) {
                        console.log("📱 [v186] Reconexión automática SSE...");
                        if (typeof initFirebaseRealtimeConnection === 'function') {
                            initFirebaseRealtimeConnection();
                        }
                    }
                }, 5000);
            };
        } catch(e) {}
    }

    // 2. Consulta inicial silenciosa de la nube con Jitter antirráfaga para múltiples usuarios
    if (typeof pullStateFromFirebaseCloud === 'function') {
        const jitterMs = Math.floor(Math.random() * 350);
        setTimeout(() => {
            pullStateFromFirebaseCloud(false);
        }, jitterMs);
    }
}
window.initFirebaseRealtimeConnection = initFirebaseRealtimeConnection;

function initCloudDatabaseConnection() {
    initFirebaseRealtimeConnection();
}
window.initCloudDatabaseConnection = initCloudDatabaseConnection;

function initFirebaseConnection() {
    initFirebaseRealtimeConnection();
}
window.initFirebaseConnection = initFirebaseConnection;

