function setAllUnitsActive(allActive) {
    [1, 2, 3, 4].forEach(u => {
        const chk = document.getElementById('checkActiveUnit' + u);
        if (chk) chk.checked = !!allActive;
    });
}
window.setAllUnitsActive = setAllUnitsActive;

function setOnlyPrimaryUnitActive() {
    const select = document.getElementById('selectBimestreActivo') || document.getElementById('officialActiveBimestreSelect');
    const primary = select ? (parseInt(select.value) || 1) : 1;
    [1, 2, 3, 4].forEach(u => {
        const chk = document.getElementById('checkActiveUnit' + u);
        if (chk) chk.checked = (u === primary);
    });
}
window.setOnlyPrimaryUnitActive = setOnlyPrimaryUnitActive;

function onPrimaryBimestreSelectChange(val) {
    const num = parseInt(val) || 1;
    const chk = document.getElementById('checkActiveUnit' + num);
    if (chk) chk.checked = true;
}
window.onPrimaryBimestreSelectChange = onPrimaryBimestreSelectChange;

async function loadLockStatus() {
    const list = document.getElementById('teacherLockList');
    const select = document.getElementById('officialActiveBimestreSelect') || document.getElementById('selectBimestre');
    const globalLockBadge = document.getElementById('globalLockBadge');

    // 🌟 Sincronización Inicial de Estado: Consultar Firebase RTDB y Firestore
    let cloudBimestre = null;
    let cloudGlobalLocked = null;
    let cloudActiveUnits = null;

    const firebaseUrl = (typeof getFirebaseDatabaseUrl === 'function') ? getFirebaseDatabaseUrl() : null;
    if (firebaseUrl && (typeof navigator === 'undefined' || navigator.onLine !== false)) {
        try {
            const rtdbConfigRes = await fetch(`${firebaseUrl}/encc_school_state/config.json?t=${Date.now()}`);
            if (rtdbConfigRes.ok) {
                const rtdbCfg = await rtdbConfigRes.json();
                if (rtdbCfg) {
                    if (rtdbCfg.activeBimestre) cloudBimestre = parseInt(rtdbCfg.activeBimestre);
                    if (rtdbCfg.globalLocked !== undefined) cloudGlobalLocked = !!rtdbCfg.globalLocked;
                    if (Array.isArray(rtdbCfg.activeUnits) && rtdbCfg.activeUnits.length > 0) {
                        cloudActiveUnits = rtdbCfg.activeUnits.map(Number);
                    }
                }
            }
        } catch(rErr) {
            console.warn("Aviso al leer config de RTDB en loadLockStatus:", rErr);
        }
    }

    if (window.FirebaseModular && window.FirebaseModular.db) {
        try {
            const { db, doc, getDoc } = window.FirebaseModular;
            const configRef = doc(db, "configuracion", "sistema");
            const snap = await withTimeout(getDoc(configRef), 3000, 'Timeout al leer configuracion/sistema').catch(() => null);
            if (snap && snap.exists()) {
                const cData = snap.data();
                const bVal = parseInt(cData.bimestreActivoOficial || cData.activeBimestre);
                if (bVal && bVal >= 1 && bVal <= 4 && !cloudBimestre) cloudBimestre = bVal;
                if (cData.globalLocked !== undefined && cloudGlobalLocked === null) cloudGlobalLocked = !!cData.globalLocked;
                if (Array.isArray(cData.activeUnits) && !cloudActiveUnits) cloudActiveUnits = cData.activeUnits.map(Number);
            }
        } catch(fsErr) {
            console.warn("Aviso al consultar configuración en Firestore (loadLockStatus):", fsErr);
        }
    }

    if (cloudBimestre && cloudBimestre >= 1 && cloudBimestre <= 4) {
        if (!STATE.config) STATE.config = {};
        STATE.config.activeBimestre = cloudBimestre;
        STATE.config.bimestreActivoOficial = cloudBimestre;
    }
    if (cloudGlobalLocked !== null) {
        if (!STATE.config) STATE.config = {};
        STATE.config.globalLocked = cloudGlobalLocked;
    }
    if (cloudActiveUnits && cloudActiveUnits.length > 0) {
        if (!STATE.config) STATE.config = {};
        STATE.config.activeUnits = cloudActiveUnits;
    } else if (!STATE.config?.activeUnits || STATE.config.activeUnits.length === 0) {
        if (!STATE.config) STATE.config = {};
        STATE.config.activeUnits = [STATE.config.activeBimestre || 1];
    }

    const activeBim = parseInt(STATE.config?.bimestreActivoOficial || STATE.config?.activeBimestre) || 1;
    const activeUnits = (Array.isArray(STATE.config?.activeUnits) && STATE.config.activeUnits.length > 0)
        ? STATE.config.activeUnits.map(Number)
        : [activeBim];

    // Sincronizar el selector desplegable con el bimestre principal
    if (select && activeBim >= 1 && activeBim <= 4) {
        select.value = String(activeBim);
        select.disabled = false;
    }

    // Sincronizar los 4 checkboxes de unidades activas
    [1, 2, 3, 4].forEach(u => {
        const chk = document.getElementById('checkActiveUnit' + u);
        if (chk) chk.checked = activeUnits.includes(u);
    });

    if (globalLockBadge) {
        globalLockBadge.className = STATE.config?.globalLocked ? 'badge badge-danger' : 'badge badge-success';
        globalLockBadge.textContent = STATE.config?.globalLocked ? 'Bloqueado General' : 'Habilitado General';
    }

    const headerBadge = document.getElementById('headerPreviewBimestreBadge');
    if (headerBadge && activeBim) {
        headerBadge.textContent = `${activeBim}º Bimestre Activo`;
    }

    if (typeof renderGradeEditRequestsTable === 'function') {
        renderGradeEditRequestsTable();
    }
    if (typeof updatePendingRequestsBadge === 'function') {
        updatePendingRequestsBadge();
    }

    if (!list) return;

    const teachers = STATE.users.filter(u => u.role === 'docente');
    if (teachers.length === 0) {
        list.innerHTML = `<div style="color:var(--text-muted); padding:10px; font-size:0.88rem;">No hay catedráticos registrados en la nómina.</div>`;
        return;
    }

    list.innerHTML = teachers.map(t => {
        const isBypassed = STATE.config?.teacherBypass?.[t.id] || false;
        return `
            <div style="display:flex; align-items:center; justify-content:space-between; padding:10px; background:var(--bg-main); border-radius:var(--radius-sm); border:1px solid var(--border-color);">
                <div>
                    <strong>${t.name}</strong><br><small style="color:var(--text-secondary);">${t.title || 'Catedrático Titular'}</small>
                </div>
                <button class="btn ${isBypassed ? 'btn-success' : 'btn-secondary'} btn-sm" onclick="toggleTeacherBypass('${t.id}')">
                    ${isBypassed ? '<i class="fa-solid fa-lock-open"></i> Habilitado Individual' : '<i class="fa-solid fa-lock"></i> Bloqueado'}
                </button>
            </div>
        `;
    }).join('');
}
window.loadLockStatus = loadLockStatus;

// Soporte transparente para resolución dual de IDs en selector de bimestre
if (typeof document !== 'undefined' && document.getElementById && !document._enccBimestreIdHook) {
    document._enccBimestreIdHook = true;
    const _origGetElem = document.getElementById.bind(document);
    document.getElementById = function(id) {
        if (id === 'officialActiveBimestreSelect') {
            return _origGetElem('selectBimestreActivo') || _origGetElem('officialActiveBimestreSelect');
        }
        if (id === 'selectBimestreActivo') {
            return _origGetElem('selectBimestreActivo') || _origGetElem('officialActiveBimestreSelect');
        }
        return _origGetElem(id);
    };
}

async function setOfficialActiveBimestre() {
    const e = arguments[0] || (typeof window !== 'undefined' && window.event ? window.event : null);
    if (e && e.preventDefault) e.preventDefault();

    if (STATE.currentRole === 'docente' && STATE.currentUser?.role !== 'admin') {
        showToast("Solo Secretaría, Dirección o Administración pueden fijar los bimestres activos.", "danger");
        return;
    }

    const btnFijar = document.getElementById('btnFijarBimestre') || 
                     document.getElementById('btnSetOfficialBimestre') || 
                     document.querySelector('button[onclick*="setOfficialActiveBimestre"]') || 
                     document.querySelector('button[onclick*="fijarBimestreOficial"]');
    const submitBtn = btnFijar;
    const currentBtn = btnFijar;
    const select = document.getElementById('officialActiveBimestreSelect') || 
                   document.getElementById('selectBimestreActivo') || 
                   document.getElementById('selectBimestre');
    const textoOriginal = '<i class="fa-solid fa-check-circle"></i> Fijar y Activar Bimestre para Maestros';

    if (btnFijar) btnFijar.disabled = true;
    if (submitBtn) submitBtn.disabled = true;
    if (btnFijar) {
        btnFijar.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Fijando en Firebase...';
    }

    const unitNum = select ? (parseInt(select.value) || 1) : 1;
    const bimestreSeleccionado = String(unitNum);

    // Obtener las unidades marcadas en los checkboxes
    let activeUnits = [];
    [1, 2, 3, 4].forEach(u => {
        const chk = document.getElementById('checkActiveUnit' + u);
        if (chk && chk.checked) activeUnits.push(u);
    });
    if (activeUnits.length === 0) {
        activeUnits = [unitNum];
        const chk = document.getElementById('checkActiveUnit' + unitNum);
        if (chk) chk.checked = true;
    }

    try {
        if (!STATE.config) STATE.config = {};
        STATE.config.activeBimestre = unitNum;
        STATE.config.bimestreActivoOficial = bimestreSeleccionado;
        STATE.config.activeUnits = activeUnits;
        STATE.config.estadoBloqueoGlobal = "HABILITADO";

        const bRoman = ['I', 'II', 'III', 'IV'][unitNum - 1] || 'I';
        const headerBadge = document.getElementById('headerPreviewBimestreBadge');
        if (headerBadge) {
            headerBadge.textContent = `${unitNum}º Bimestre Activo`;
        }

        // Limpieza preventiva de listeners
        if (typeof unsubscribeCurrentGradebookListener === 'function') {
            unsubscribeCurrentGradebookListener();
        }

        const nowTime = Date.now();
        const fechaModificacion = new Date().toISOString();
        const ultimaActualizacion = fechaModificacion;

        if (typeof localStorage !== 'undefined') {
            try { localStorage.setItem('ENCCO_LAST_LOCAL_MODIFIED', String(nowTime)); } catch(e) {}
        }

        // Notificación inter-pestañas local (0ms)
        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            try {
                _enccBroadcastChannel.postMessage({
                    type: 'NODE_UPDATED',
                    node: 'config',
                    data: { activeBimestre: unitNum, activeUnits: activeUnits, bimestreActivoOficial: bimestreSeleccionado },
                    timestamp: nowTime
                });
            } catch(bcErr) {}
        }

        const configPayload = {
            activeBimestre: unitNum,
            bimestreActivoOficial: bimestreSeleccionado,
            activeUnits: activeUnits,
            estadoBloqueoGlobal: "HABILITADO",
            ultimaActualizacion: ultimaActualizacion,
            fechaModificacion: new Date().toISOString(),
            lastModified: nowTime
        };

        // 🌟 Sincronización Realtime Database inmediata dual (root y encc_school_state)
        const rtdbPromise = (async () => {
            if (typeof EnccoCloudSync !== 'undefined') {
                if (typeof EnccoCloudSync.patchNode === 'function') {
                    await EnccoCloudSync.patchNode('config', configPayload);
                }
                if (typeof EnccoCloudSync.syncNode === 'function') {
                    await EnccoCloudSync.syncNode('config', STATE.config);
                }
            }
        })();

        // 🌟 Sincronización Firestore múltiple y coordinada
        const fsPromise = (async () => {
            const modular = window.FirebaseModular;
            if (modular && modular.db && typeof modular.doc === 'function' && typeof modular.setDoc === 'function') {
                const { db, doc, setDoc } = modular;
                const configRef = doc(db, "configuracion", "sistema");
                const bRef = doc(db, 'config', 'bimestre_activo');
                const bData = { bimestreActivoOficial: bimestreSeleccionado, activeBimestre: unitNum, activeUnits, lastModified: nowTime };
                const bimActRef = doc(db, 'configuracion', 'bimestreActivo');
                const genRef = doc(db, 'config', 'general');
                const sysRef = doc(db, 'configuracion_sistema', 'global');

                const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout Firestore')), 8000));
                await setDoc(bRef, bData, { merge: true });
                await Promise.race([
                    Promise.all([
                        setDoc(configRef, configPayload, { merge: true }),
                        setDoc(bimActRef, configPayload, { merge: true }),
                        setDoc(genRef, configPayload, { merge: true }),
                        setDoc(sysRef, configPayload, { merge: true })
                    ]),
                    timeoutPromise
                ]);
            }
        })();

        await Promise.allSettled([fsPromise, rtdbPromise]);

        const unitsNames = activeUnits.map(u => `U${u}`).join(', ');
        showToast(`¡Configuración de bimestres guardada en Firebase! Bimestre Principal: ${unitNum}º (${bRoman}). Unidades Habilitadas: [${unitsNames}].`, "success");

        if (typeof populateGradebookBimestreSelect === 'function') populateGradebookBimestreSelect();
        if (typeof loadLockStatus === 'function') loadLockStatus();
        if (typeof renderCurrentView === 'function') renderCurrentView();
    } catch(err) {
        console.error("Error al fijar bimestres:", err);
        showToast("Error al fijar bimestres: " + (err.message || err), "danger");
    } finally {
        if (currentBtn) currentBtn.disabled = false;
        if (submitBtn) submitBtn.disabled = false;
        if (btnFijar) btnFijar.disabled = false;
        if (btnFijar) btnFijar.innerHTML = textoOriginal;
    }
}
window.setOfficialActiveBimestre = setOfficialActiveBimestre;
window.fijarBimestreOficial = setOfficialActiveBimestre;
async function fijarBimestreOficial(e) {
    return setOfficialActiveBimestre(e);
}

async function toggleGlobalLock() {
    if (STATE.currentRole === 'docente' && STATE.currentUser?.role !== 'admin') return;
    if (!STATE.config) STATE.config = {};
    STATE.config.globalLocked = !STATE.config.globalLocked;
    const isLocked = STATE.config.globalLocked;
    const badge = document.getElementById('globalLockBadge');
    if (badge) {
        badge.className = isLocked ? 'badge badge-danger' : 'badge badge-success';
        badge.textContent = isLocked ? 'Bloqueado General' : 'Habilitado General';
    }

    const nowTime = Date.now();
    try {
        if (typeof localStorage !== 'undefined') {
            localStorage.setItem('ENCCO_LAST_LOCAL_MODIFIED', String(nowTime));
        }
    } catch(e) {}

    if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
        try {
            _enccBroadcastChannel.postMessage({
                type: 'NODE_UPDATED',
                node: 'config',
                data: { globalLocked: isLocked },
                timestamp: nowTime
            });
        } catch(bcErr) {}
    }

    // 🌟 A. Persistencia Atómica en Firestore (colecciones independientes configuracion_sistema/global y config/control_bloqueo con merge: true)
    if (window.FirebaseModular && window.FirebaseModular.db) {
        try {
            const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
            const lockRef = doc(db, 'config', 'control_bloqueo');
            const gRef = doc(db, 'config', 'general');
            const sysRef = doc(db, 'configuracion_sistema', 'global');
            const lockData = { globalLocked: isLocked, lastModified: nowTime };

            if (typeof updateDoc === 'function') {
                try { await updateDoc(lockRef, lockData); } catch(e) { if (typeof setDoc === 'function') await setDoc(lockRef, lockData, { merge: true }); }
                try { await updateDoc(sysRef, lockData); } catch(e) { if (typeof setDoc === 'function') await setDoc(sysRef, lockData, { merge: true }); }
                try { await updateDoc(gRef, { "config.globalLocked": isLocked, lastModified: nowTime }); } catch(e) { if (typeof setDoc === 'function') await setDoc(gRef, { config: { globalLocked: isLocked } }, { merge: true }); }
            } else if (typeof setDoc === 'function') {
                await setDoc(lockRef, lockData, { merge: true });
                await setDoc(sysRef, lockData, { merge: true });
                await setDoc(gRef, { config: { globalLocked: isLocked } }, { merge: true });
            }
            console.log(`🔥 [Firestore] Control de Bloqueo (${isLocked}) persistido con merge: true en configuracion_sistema/global y config/control_bloqueo.`);
        } catch(fsErr) {
            console.warn("Aviso al guardar bloqueo en Firestore:", fsErr);
        }
    }

    // 🌟 B. Persistencia Atómica Parcial en Firebase Realtime Database (PATCH / update() atómico exclusivo de globalLocked)
    if (typeof EnccoCloudSync !== 'undefined' && typeof EnccoCloudSync.patchNode === 'function') {
        await EnccoCloudSync.patchNode('config', { globalLocked: isLocked, lastModified: nowTime });
    } else if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        await EnccoCloudSync.syncNode('config', STATE.config);
    }

    showToast(`Carga de notas ${isLocked ? 'BLOQUEADA' : 'HABILITADA'} globalmente.`, isLocked ? "warning" : "success");
}
window.toggleGlobalLock = toggleGlobalLock;

async function toggleTeacherBypass(teacherId) {
    if (STATE.currentRole === 'docente' && STATE.currentUser?.role !== 'admin') return;
    if (!STATE.config) STATE.config = {};
    if (!STATE.config.teacherBypass) STATE.config.teacherBypass = {};
    STATE.config.teacherBypass[teacherId] = !STATE.config.teacherBypass[teacherId];
    saveStateToLocalStorage();

    const nowTime = Date.now();
    // 🌟 A. Persistencia Atómica en Firestore (config/control_bloqueo y config/general con merge: true)
    if (window.FirebaseModular && window.FirebaseModular.db) {
        try {
            const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
            const lockRef = doc(db, 'config', 'control_bloqueo');
            const genRef = doc(db, 'config', 'general');
            const payload = { teacherBypass: STATE.config.teacherBypass, lastModified: nowTime };
            if (typeof updateDoc === 'function') {
                try { await updateDoc(lockRef, payload); } catch(e) { if (typeof setDoc === 'function') await setDoc(lockRef, payload, { merge: true }); }
                try { await updateDoc(genRef, { "config.teacherBypass": STATE.config.teacherBypass, lastModified: nowTime }); } catch(e) { if (typeof setDoc === 'function') await setDoc(genRef, { config: { teacherBypass: STATE.config.teacherBypass } }, { merge: true }); }
            } else if (typeof setDoc === 'function') {
                await setDoc(lockRef, payload, { merge: true });
                await setDoc(genRef, { config: { teacherBypass: STATE.config.teacherBypass } }, { merge: true });
            }
        } catch(fsErr) {
            console.warn("Aviso al guardar bypass en Firestore:", fsErr);
        }
    }

    // 🌟 B. Sincronización atómica aislada en Realtime Database (SÓLO nodo 'config')
    if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        await EnccoCloudSync.syncNode('config', STATE.config);
    }

    loadLockStatus();
    showToast("Permiso individual de docente actualizado y guardado.", "info");
}
window.toggleTeacherBypass = toggleTeacherBypass;

// ==========================================================================
// 🔒 GESTIÓN DE SOLICITUDES DE HABILITACIÓN DE EDICIÓN DE NOTAS (BIMESTRES CERRADOS)
// ==========================================================================

function isGradebookEditableForUser(pensumId, unit) {
    if (!pensumId) {
        const sel = document.getElementById('teacherCourseSelect');
        if (sel && sel.value) pensumId = sel.value;
    }
    const isDocente = (STATE.currentRole === 'docente');
    const currentUser = STATE.currentUser || (STATE.users || []).find(u => u.role === 'docente');

    // Dirección, Secretaría y Super Administrador siempre tienen acceso total de modificación
    if (!isDocente) {
        return { editable: true, reason: 'admin' };
    }

    const activeBim = parseInt(STATE.config?.activeBimestre) || 1;
    const currentUnit = parseInt(unit) || activeBim;
    const activeUnits = (Array.isArray(STATE.config?.activeUnits) && STATE.config.activeUnits.length > 0)
        ? STATE.config.activeUnits.map(Number)
        : [activeBim];

    // Verificar si el sistema está bajo bloqueo global
    const isGlobalLocked = !!STATE.config?.globalLocked;
    const hasGlobalBypass = !!(currentUser && STATE.config?.teacherBypass && STATE.config.teacherBypass[currentUser.id]);

    // Verificar si existe solicitud aprobada y vigente para este docente, curso y bimestre
    const now = Date.now();
    const requests = Array.isArray(STATE.gradeEditRequests) ? STATE.gradeEditRequests : [];
    const approvedRequest = requests.find(req => {
        const matchTeacher = (req.teacherId === currentUser?.id || (currentUser?.email && req.teacherEmail === currentUser?.email));
        if (!matchTeacher) return false;
        if (req.pensumId && pensumId && req.pensumId !== pensumId) return false;
        if (parseInt(req.bimestre) !== currentUnit) return false;
        if (req.status !== 'approved') return false;
        if (req.expiresAt && new Date(req.expiresAt).getTime() < now) return false; // Ya venció
        return true;
    });

    if (approvedRequest) {
        return {
            editable: true,
            reason: 'unlocked_request',
            request: approvedRequest
        };
    }

    // Si es un bimestre / unidad activa habilitada por Dirección
    if (activeUnits.includes(currentUnit) || currentUnit === activeBim) {
        if (isGlobalLocked && !hasGlobalBypass) {
            return {
                editable: false,
                reason: 'global_locked',
                message: 'El ingreso de calificaciones está bloqueado temporalmente por Dirección y Secretaría.'
            };
        }
        return { editable: true, reason: 'active_bimestre' };
    }

    // Si no es un bimestre activo y no cuenta con solicitud aprobada vigente
    const activeNames = activeUnits.map(u => 'Unidad ' + u).join(', ');
    return {
        editable: false,
        reason: 'bimestre_closed',
        message: 'La Unidad ' + currentUnit + ' se encuentra cerrada oficialmente (Las unidades habilitadas son: ' + activeNames + ').'
    };
}
window.isGradebookEditableForUser = isGradebookEditableForUser;

function getPendingGradeEditRequest(teacherId, pensumId, unit) {
    const requests = Array.isArray(STATE.gradeEditRequests) ? STATE.gradeEditRequests : [];
    return requests.find(req => {
        const matchTeacher = (req.teacherId === teacherId || (STATE.currentUser?.email && req.teacherEmail === STATE.currentUser?.email));
        if (!matchTeacher) return false;
        if (req.pensumId && pensumId && req.pensumId !== pensumId) return false;
        if (parseInt(req.bimestre) !== parseInt(unit)) return false;
        return req.status === 'pending';
    });
}
window.getPendingGradeEditRequest = getPendingGradeEditRequest;

function openGradeEditRequestModal(pensumId, unit) {
    const isDocente = (STATE.currentRole === 'docente');
    const currentUser = STATE.currentUser || (STATE.users || []).find(u => u.role === 'docente');

    let targetPensum = (STATE.pensum || []).find(p => p.id === pensumId);
    if (!targetPensum) {
        const selId = document.getElementById('teacherCourseSelect')?.value;
        targetPensum = (STATE.pensum || []).find(p => p.id === selId);
    }
    if (!targetPensum) {
        showToast("Seleccione una clase válida para solicitar habilitación.", "warning");
        return;
    }

    const currentUnit = parseInt(unit) || parseInt(document.getElementById('gradebookBimestreSelect')?.value) || 1;
    const bNamesMap = { 1: 'Unidad 1 / I Bimestre', 2: 'Unidad 2 / II Bimestre', 3: 'Unidad 3 / III Bimestre', 4: 'Unidad 4 / IV Bimestre' };

    const modal = document.getElementById('modalGradeEditRequest');
    if (!modal) return;

    const elPensum = document.getElementById('reqModalPensumId');
    const elBim = document.getElementById('reqModalBimestre');
    const elTeacher = document.getElementById('reqModalTeacherName');
    const elBimText = document.getElementById('reqModalBimestreText');
    const elSubject = document.getElementById('reqModalSubject');
    const elGrade = document.getElementById('reqModalGrade');
    const elReason = document.getElementById('reqModalReason');
    const elDuration = document.getElementById('reqModalDuration');

    if (elPensum) elPensum.value = targetPensum.id || '';
    if (elBim) elBim.value = currentUnit;
    if (elTeacher) elTeacher.value = (currentUser ? currentUser.name : 'Catedrático Titular');
    if (elBimText) elBimText.value = bNamesMap[currentUnit] || ('Unidad ' + currentUnit);
    if (elSubject) elSubject.value = targetPensum.subject || '';
    if (elGrade) elGrade.value = (targetPensum.grade || '') + ' (' + (targetPensum.section || '') + ')';
    if (elReason) elReason.value = '';
    if (elDuration) elDuration.value = '48';

    modal.style.setProperty('display', 'flex', 'important');
}
window.openGradeEditRequestModal = openGradeEditRequestModal;

function closeGradeEditRequestModal() {
    const modal = document.getElementById('modalGradeEditRequest');
    if (modal) modal.style.setProperty('display', 'none', 'important');
}
window.closeGradeEditRequestModal = closeGradeEditRequestModal;

async function submitGradeEditRequest(event) {
    if (event && event.preventDefault) event.preventDefault();
    if (event && event.stopPropagation) event.stopPropagation();

    const pensumId = document.getElementById('reqModalPensumId')?.value?.trim();
    const unit = parseInt(document.getElementById('reqModalBimestre')?.value) || 1;
    const reason = (document.getElementById('reqModalReason')?.value || '').trim();
    const durationHours = parseInt(document.getElementById('reqModalDuration')?.value) || 48;

    if (!pensumId || pensumId === 'undefined' || pensumId === 'null') {
        console.error("Error: ID de la cátedra/pensum no encontrado o indefinido.");
        showToast("Error: ID de la cátedra no identificado.", "danger");
        return;
    }

    if (!reason) {
        showToast("Por favor proporcione el motivo o justificación académica de la solicitud.", "warning");
        return;
    }

    const currentUser = STATE.currentUser || (STATE.users || []).find(u => u.role === 'docente');
    const targetPensum = (STATE.pensum || []).find(p => p.id === pensumId);

    if (!Array.isArray(STATE.gradeEditRequests)) {
        STATE.gradeEditRequests = [];
    }

    const submitBtn = document.getElementById('gradeEditReqSubmitBtn') || document.querySelector('#formGradeEditRequest button[type="submit"]');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : 'Enviar Solicitud a Dirección';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        // Verificar si ya existe una solicitud pendiente idéntica
        const existingPending = STATE.gradeEditRequests.find(r => 
            r.status === 'pending' &&
            (r.teacherId === currentUser?.id || (currentUser?.email && r.teacherEmail === currentUser?.email)) &&
            r.pensumId === pensumId &&
            parseInt(r.bimestre) === unit
        );

        if (existingPending) {
            showToast("Ya existe una solicitud pendiente de revisión para este curso y bimestre.", "info");
            closeGradeEditRequestModal();
            return;
        }

        const newRequest = {
            id: 'REQ_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6),
            teacherId: currentUser?.id || 'DOCENTE_ID',
            teacherName: currentUser?.name || 'Catedrático Titular',
            teacherEmail: currentUser?.email || '',
            pensumId: pensumId,
            subject: targetPensum?.subject || 'Asignatura',
            grade: targetPensum?.grade || targetPensum?.gradeCode || 'Grado',
            section: targetPensum?.section || 'Sección',
            bimestre: unit,
            reason: reason,
            durationHours: durationHours,
            status: 'pending',
            createdAt: new Date().toISOString(),
            resolvedAt: null,
            resolvedBy: null
        };

        STATE.gradeEditRequests.push(newRequest);
        const nowTime = Date.now();
        STATE.lastModified = nowTime;

        // 🌟 A. Persistencia Atómica en Firestore
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
                const reqRef = doc(db, 'gradeEditRequests', newRequest.id);
                const reqPayload = { ...newRequest, lastModified: nowTime };
                const fsAction = (typeof setDoc === 'function') 
                    ? setDoc(reqRef, reqPayload, { merge: true }) 
                    : Promise.resolve();
                await withTimeout(fsAction, 8000, 'Tiempo de espera en Firestore agotado.');
            } catch(fsErr) {
                console.warn("Aviso al guardar solicitud en Firestore:", fsErr);
            }
        }

        // 🌟 B. Sincronización en Realtime Database
        let ok = false;
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            ok = await withTimeout(EnccoCloudSync.syncNode('gradeEditRequests', STATE.gradeEditRequests), 8000, 'Tiempo de espera en Realtime Database agotado.');
        } else {
            ok = true;
        }

        if (!ok) {
            throw new Error("El servidor de Firebase no confirmó la solicitud de habilitación.");
        }

        saveStateToLocalStorage();
        closeGradeEditRequestModal();
        renderGradebook();
        if (typeof updateUserAlertsUI === 'function') updateUserAlertsUI();

        showToast("Solicitud enviada a Dirección y confirmada en Firebase con éxito.", "success");
    } catch(err) {
        console.error("❌ Error al enviar solicitud:", err);
        showToast(`Error al guardar en Firebase: ${err.message || err}`, "danger");
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml;
        }
    }
}
window.submitGradeEditRequest = submitGradeEditRequest;

let _activeGradeEditFilter = 'pending';

function filterGradeEditRequests(filter) {
    _activeGradeEditFilter = filter;
    ['btnFilterReqPending', 'btnFilterReqApproved', 'btnFilterReqAll'].forEach(id => {
        const btn = document.getElementById(id);
        if (btn) {
            btn.style.background = 'white';
            btn.style.color = 'var(--text-primary)';
            btn.style.fontWeight = '600';
        }
    });

    const activeBtn = document.getElementById(
        filter === 'pending' ? 'btnFilterReqPending' : 
        (filter === 'approved' ? 'btnFilterReqApproved' : 'btnFilterReqAll')
    );
    if (activeBtn) {
        activeBtn.style.background = '#8b5cf6';
        activeBtn.style.color = 'white';
        activeBtn.style.fontWeight = '700';
    }

    renderGradeEditRequestsTable();
}
window.filterGradeEditRequests = filterGradeEditRequests;

function updatePendingRequestsBadge() {
    const badge = document.getElementById('pendingGradeRequestsBadge');
    if (!badge) return;
    const requests = Array.isArray(STATE.gradeEditRequests) ? STATE.gradeEditRequests : [];
    const pendingCount = requests.filter(r => r.status === 'pending').length;
    if (pendingCount > 0) {
        badge.style.display = 'inline-block';
        badge.textContent = pendingCount.toString();
    } else {
        badge.style.display = 'none';
    }
}
window.updatePendingRequestsBadge = updatePendingRequestsBadge;

function renderGradeEditRequestsTable() {
    const tbody = document.getElementById('gradeEditRequestsTableBody');
    if (!tbody) return;

    const requests = Array.isArray(STATE.gradeEditRequests) ? STATE.gradeEditRequests : [];
    const now = Date.now();

    const pendingCount = requests.filter(r => r.status === 'pending').length;
    const approvedCount = requests.filter(r => r.status === 'approved' && (!r.expiresAt || new Date(r.expiresAt).getTime() > now)).length;
    const allCount = requests.length;

    const elP = document.getElementById('countReqPending');
    const elA = document.getElementById('countReqApproved');
    const elAll = document.getElementById('countReqAll');
    if (elP) elP.textContent = pendingCount.toString();
    if (elA) elA.textContent = approvedCount.toString();
    if (elAll) elAll.textContent = allCount.toString();

    updatePendingRequestsBadge();

    let filtered = requests;
    if (_activeGradeEditFilter === 'pending') {
        filtered = requests.filter(r => r.status === 'pending');
    } else if (_activeGradeEditFilter === 'approved') {
        filtered = requests.filter(r => r.status === 'approved' && (!r.expiresAt || new Date(r.expiresAt).getTime() > now));
    }

    filtered = filtered.slice().sort((a, b) => new Date(b.requestedAt || 0).getTime() - new Date(a.requestedAt || 0).getTime());

    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding:24px; color:var(--text-muted); font-size:0.9rem;"><i class="fa-solid fa-inbox"></i> No hay solicitudes registradas en esta categoría.</td></tr>';
        return;
    }

    const bNames = { 1: 'Unidad 1', 2: 'Unidad 2', 3: 'Unidad 3', 4: 'Unidad 4' };

    tbody.innerHTML = filtered.map(req => {
        const isPending = (req.status === 'pending');
        const isApproved = (req.status === 'approved');
        const isExpired = isApproved && req.expiresAt && (new Date(req.expiresAt).getTime() <= now);
        const isRejected = (req.status === 'rejected');
        const isRevoked = (req.status === 'revoked');

        let statusBadge = '';
        if (isPending) {
            statusBadge = '<span class="badge" style="background:#fef3c7; color:#92400e; border:1px solid #fcd34d; font-weight:700;"><i class="fa-solid fa-clock"></i> Pendiente</span>';
        } else if (isApproved && !isExpired) {
            statusBadge = '<span class="badge badge-success" style="font-weight:700;"><i class="fa-solid fa-check-circle"></i> Aprobada / Activa</span>';
        } else if (isExpired) {
            statusBadge = '<span class="badge badge-secondary" style="font-weight:700;"><i class="fa-solid fa-hourglass-end"></i> Expirada</span>';
        } else if (isRejected) {
            statusBadge = '<span class="badge badge-danger" style="font-weight:700;"><i class="fa-solid fa-ban"></i> Rechazada</span>';
        } else if (isRevoked) {
            statusBadge = '<span class="badge" style="background:#e2e8f0; color:#475569; border:1px solid #cbd5e1; font-weight:700;"><i class="fa-solid fa-lock"></i> Revocada</span>';
        }

        let timeCol = '';
        if (isPending) {
            timeCol = '<span>' + (req.requestedHours || 48) + ' hrs solicitadas</span>';
        } else if (isApproved && !isExpired) {
            const expDate = new Date(req.expiresAt);
            const diffMs = expDate.getTime() - now;
            const remainingHrs = Math.max(0, Math.round(diffMs / 3600000));
            timeCol = '<div style="font-size:0.8rem;"><strong>Vence:</strong> ' + expDate.toLocaleDateString() + ' ' + expDate.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) + '<br><span class="badge badge-info" style="font-size:0.7rem; margin-top:2px;"><i class="fa-solid fa-stopwatch"></i> Restan ~' + remainingHrs + 'h</span></div>';
        } else if (isApproved && isExpired) {
            timeCol = '<small style="color:var(--text-muted);">Venció el ' + new Date(req.expiresAt).toLocaleDateString() + '</small>';
        } else {
            timeCol = '<small style="color:var(--text-muted);">' + (req.requestedHours || 48) + ' hrs</small>';
        }

        let actionBtns = '';
        if (isPending) {
            actionBtns = '<div style="display:flex; gap:6px; justify-content:center;"><button type="button" class="btn btn-xs btn-success" onclick="approveGradeEditRequest(' + req.id + ')" title="Aprobar solicitud de edición" style="font-weight:700;"><i class="fa-solid fa-check"></i> Aprobar</button><button type="button" class="btn btn-xs btn-danger" onclick="rejectGradeEditRequest(' + req.id + ')" title="Rechazar solicitud"><i class="fa-solid fa-xmark"></i> Rechazar</button></div>';
        } else if (isApproved && !isExpired) {
            actionBtns = '<div style="display:flex; gap:6px; justify-content:center;"><button type="button" class="btn btn-xs btn-outline-danger" onclick="revokeGradeEditRequest(' + req.id + ')" title="Revocar habilitación anticipadamente" style="font-size:0.75rem;"><i class="fa-solid fa-lock"></i> Revocar</button></div>';
        } else {
            actionBtns = '<span style="color:var(--text-muted); font-size:0.75rem;">Completada</span>';
        }

        const dateStr = req.requestedAt ? new Date(req.requestedAt).toLocaleString([], {dateStyle:'short', timeStyle:'short'}) : '—';

        return '<tr>' +
            '<td style="text-align:center; font-size:0.8rem; font-weight:600;">' + dateStr + '</td>' +
            '<td><strong>' + escapeHtml(req.teacherName || 'Docente') + '</strong>' + (req.teacherEmail ? '<br><small style="color:var(--text-muted); font-size:0.75rem;">' + escapeHtml(req.teacherEmail) + '</small>' : '') + '</td>' +
            '<td><strong>' + escapeHtml(req.subject || 'Asignatura') + '</strong><br><small style="color:var(--text-secondary);">' + escapeHtml(req.grade || '') + (req.section ? ' (' + escapeHtml(req.section) + ')' : '') + '</small></td>' +
            '<td style="text-align:center; font-weight:700; color:#1e40af;">' + (bNames[req.bimestre] || ('Unidad ' + req.bimestre)) + '</td>' +
            '<td style="max-width:240px; word-break:break-word; font-size:0.84rem;">"' + escapeHtml(req.reason || 'Sin justificación') + '"' + (req.approvedBy ? '<br><small style="color:#047857;">Aprobado por: ' + escapeHtml(req.approvedBy) + '</small>' : '') + '</td>' +
            '<td style="text-align:center;">' + timeCol + '</td>' +
            '<td style="text-align:center;">' + statusBadge + '</td>' +
            '<td style="text-align:center;">' + actionBtns + '</td>' +
        '</tr>';
    }).join('');
}
window.renderGradeEditRequestsTable = renderGradeEditRequestsTable;

async function approveGradeEditRequest(requestId, customHours) {
    if (STATE.currentRole === 'docente' && STATE.currentUser?.role !== 'admin') {
        showToast("Solo Dirección o Administración pueden autorizar solicitudes de edición.", "danger");
        return;
    }

    if (!Array.isArray(STATE.gradeEditRequests)) return;
    const req = STATE.gradeEditRequests.find(r => r.id === requestId);
    if (!req) {
        showToast("Solicitud no encontrada.", "danger");
        return;
    }

    const hours = parseInt(customHours) || parseInt(req.requestedHours) || 48;
    const now = Date.now();
    const expiresAt = new Date(now + hours * 3600000).toISOString();

    req.status = 'approved';
    req.approvedBy = STATE.currentUser?.name || 'Dirección General';
    req.approvedAt = new Date().toISOString();
    req.expiresAt = expiresAt;

    saveStateToLocalStorage();

    // 🌟 A. Persistencia Atómica en Firestore
    if (window.FirebaseModular && window.FirebaseModular.db) {
        try {
            const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
            const reqRef = doc(db, 'gradeEditRequests', req.id);
            const reqData = { status: 'approved', approvedBy: req.approvedBy, approvedAt: req.approvedAt, expiresAt: req.expiresAt, lastModified: Date.now() };
            if (typeof updateDoc === 'function') {
                try { await updateDoc(reqRef, reqData); } catch(e) { if (typeof setDoc === 'function') await setDoc(reqRef, reqData, { merge: true }); }
            } else if (typeof setDoc === 'function') {
                await setDoc(reqRef, reqData, { merge: true });
            }
        } catch(fsErr) {
            console.warn("Aviso al aprobar solicitud en Firestore:", fsErr);
        }
    }

    // 🌟 B. Sincronización atómica aislada en RTDB
    if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        await EnccoCloudSync.syncNode('gradeEditRequests', STATE.gradeEditRequests);
    }

    showToast('¡Habilitación aprobada exitosamente por ' + hours + ' horas para ' + req.teacherName + '!', "success");
    renderGradeEditRequestsTable();
    updatePendingRequestsBadge();

    if (document.getElementById('view-gradebook')?.classList.contains('active')) {
        loadTeacherGradebook();
    }
}
window.approveGradeEditRequest = approveGradeEditRequest;

async function rejectGradeEditRequest(requestId) {
    if (STATE.currentRole === 'docente' && STATE.currentUser?.role !== 'admin') {
        showToast("Solo Dirección o Administración pueden rechazar solicitudes de edición.", "danger");
        return;
    }

    if (!Array.isArray(STATE.gradeEditRequests)) return;
    const req = STATE.gradeEditRequests.find(r => r.id === requestId);
    if (!req) return;

    req.status = 'rejected';
    req.approvedBy = STATE.currentUser?.name || 'Dirección General';
    req.approvedAt = new Date().toISOString();

    saveStateToLocalStorage();

    // 🌟 A. Persistencia Atómica en Firestore
    if (window.FirebaseModular && window.FirebaseModular.db) {
        try {
            const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
            const reqRef = doc(db, 'gradeEditRequests', req.id);
            const reqData = { status: 'rejected', approvedBy: req.approvedBy, approvedAt: req.approvedAt, lastModified: Date.now() };
            if (typeof updateDoc === 'function') {
                try { await updateDoc(reqRef, reqData); } catch(e) { if (typeof setDoc === 'function') await setDoc(reqRef, reqData, { merge: true }); }
            } else if (typeof setDoc === 'function') {
                await setDoc(reqRef, reqData, { merge: true });
            }
        } catch(fsErr) {
            console.warn("Aviso al rechazar solicitud en Firestore:", fsErr);
        }
    }

    // 🌟 B. Sincronización atómica aislada en RTDB
    if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        await EnccoCloudSync.syncNode('gradeEditRequests', STATE.gradeEditRequests);
    }

    showToast("Solicitud de edición de notas rechazada.", "info");
    renderGradeEditRequestsTable();
    updatePendingRequestsBadge();

    if (document.getElementById('view-gradebook')?.classList.contains('active')) {
        loadTeacherGradebook();
    }
}
window.rejectGradeEditRequest = rejectGradeEditRequest;

async function revokeGradeEditRequest(requestId) {
    if (STATE.currentRole === 'docente' && STATE.currentUser?.role !== 'admin') {
        showToast("Solo Dirección o Administración pueden revocar habilitaciones.", "danger");
        return;
    }

    if (!Array.isArray(STATE.gradeEditRequests)) return;
    const req = STATE.gradeEditRequests.find(r => r.id === requestId);
    if (!req) return;

    req.status = 'revoked';
    req.revokedAt = new Date().toISOString();
    req.expiresAt = new Date().toISOString();

    saveStateToLocalStorage();

    // 🌟 A. Persistencia Atómica en Firestore
    if (window.FirebaseModular && window.FirebaseModular.db) {
        try {
            const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
            const reqRef = doc(db, 'gradeEditRequests', req.id);
            const reqData = { status: 'revoked', approvedBy: req.approvedBy, approvedAt: req.approvedAt, expiresAt: req.expiresAt, lastModified: Date.now() };
            if (typeof updateDoc === 'function') {
                try { await updateDoc(reqRef, reqData); } catch(e) { if (typeof setDoc === 'function') await setDoc(reqRef, reqData, { merge: true }); }
            } else if (typeof setDoc === 'function') {
                await setDoc(reqRef, reqData, { merge: true });
            }
        } catch(fsErr) {
            console.warn("Aviso al revocar solicitud en Firestore:", fsErr);
        }
    }

    // 🌟 B. Sincronización atómica aislada en RTDB
    if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        await EnccoCloudSync.syncNode('gradeEditRequests', STATE.gradeEditRequests);
    }

    showToast("Habilitación revocada. El bimestre vuelve a estar en Solo Lectura para el docente.", "warning");
    renderGradeEditRequestsTable();
    updatePendingRequestsBadge();

    if (document.getElementById('view-gradebook')?.classList.contains('active')) {
        loadTeacherGradebook();
    }
}
window.revokeGradeEditRequest = revokeGradeEditRequest;

// ==========================================================================
// 13. GESTIÓN COMPLETA DE MAESTROS Y USUARIOS (SUPERPODERES DE ADMIN)
// ==========================================================================
function renderUsersTable(filterVal = '') {
    const tbody = document.getElementById('usersTableBody');
    if (!tbody) return;

    // Asegurar colección sin duplicados
    if (Array.isArray(STATE.users)) {
        STATE.users = deduplicateUsersCollection(STATE.users);
    }

    // Calcular KPIs de Renglón 011 / 021 y Género en tiempo real
    const allTeachers = (STATE.users || []).filter(u => u.role === 'docente' || u.id.startsWith('usr-doc-'));
    let count011_H = 0, count011_M = 0;
    let count021_H = 0, count021_M = 0;
    let countTotal_H = 0, countTotal_M = 0;

    allTeachers.forEach(u => {
        const r = u.renglon || '011';
        const g = u.gender || 'Masculino';
        if (g === 'Femenino') {
            countTotal_M++;
            if (r === '021') count021_M++;
            else count011_M++;
        } else {
            countTotal_H++;
            if (r === '021') count021_H++;
            else count011_H++;
        }
    });

    const kpi011El = document.getElementById('kpiRenglon011Count');
    const kpi021El = document.getElementById('kpiRenglon021Count');
    const kpiTotEl = document.getElementById('kpiGenderTotalCount');

    if (kpi011El) kpi011El.innerHTML = `<i class="fa-solid fa-id-card"></i> 011: <strong>${count011_H + count011_M}</strong> (H:${count011_H}|M:${count011_M})`;
    if (kpi021El) kpi021El.innerHTML = `<i class="fa-solid fa-file-contract"></i> 021: <strong>${count021_H + count021_M}</strong> (H:${count021_H}|M:${count021_M})`;
    if (kpiTotEl) kpiTotEl.innerHTML = `<i class="fa-solid fa-users"></i> Total: <strong>${allTeachers.length}</strong> (H:${countTotal_H}|M:${countTotal_M})`;

    const roleFilter = document.getElementById('userRoleFilterSelect')?.value || 'ALL';
    const q = (typeof filterVal === 'string' ? filterVal : (document.getElementById('userSearchInput')?.value || '')).toLowerCase();

    let list = STATE.users || [];
    if (roleFilter === 'docente') {
        list = list.filter(u => u.role === 'docente');
    } else if (roleFilter === 'profesor_auxiliar' || roleFilter === 'auxiliar') {
        list = list.filter(u => u.role === 'profesor_auxiliar');
    } else if (roleFilter.includes('admin')) {
        list = list.filter(u => u.role === 'admin' || u.role === 'director' || u.role === 'secretaria');
    }

    if (q) {
        list = list.filter(u => (u.name || '').toLowerCase().includes(q) || (u.email || '').toLowerCase().includes(q) || (u.title || '').toLowerCase().includes(q) || (u.renglon || '').toLowerCase().includes(q));
    }

    const canViewPasswords = (STATE.currentRole === 'admin' || STATE.currentRole === 'director' || STATE.currentUser?.role === 'admin');
    const canEditUsers = (STATE.currentRole === 'admin' || STATE.currentRole === 'director' || STATE.currentRole === 'secretaria');

    tbody.innerHTML = list.map(u => {
        const renglonBadge = u.renglon === '021' 
            ? `<span class="badge" style="background:#ffedd5; color:#c2410c; border:1px solid #fed7aa; font-weight:800; font-size:0.70rem; padding:1px 4px;">021</span>`
            : `<span class="badge" style="background:#dcfce7; color:#15803d; border:1px solid #86efac; font-weight:800; font-size:0.70rem; padding:1px 4px;">011</span>`;

        const genderBadge = u.gender === 'Femenino'
            ? `<span class="badge" style="background:#fce7f3; color:#be185d; border:1px solid #fbcfe8; font-weight:700; font-size:0.70rem; padding:1px 4px;">Femenino</span>`
            : `<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #7dd3fc; font-weight:700; font-size:0.70rem; padding:1px 4px;">Masculino</span>`;

        const isMaster = (u.id === 'usr-admin-master');
        const passCell = canViewPasswords ? 
            `<div style="display:flex; align-items:center; gap:4px;">
                <code id="userPassCode_${u.id}" style="color:var(--brand-orange); font-weight:700; font-size:0.75rem;">${u.password || 'C@rolina1'}</code>
                <button class="btn btn-secondary btn-xs" onclick="toggleUserTableRowPassword('${u.id}')" title="Ver/Ocultar" style="padding:1px 4px; font-size:0.70rem; height:20px; min-width:20px;">
                    <i class="fa-solid fa-eye-slash" id="userPassIcon_${u.id}"></i>
                </button>
            </div>` : 
            `<code style="font-size:0.75rem;">••••••••</code>`;

        const roleBadge = `<span class="user-role-badge role-${u.role}" style="font-size:0.70rem; padding:1px 5px; text-transform:uppercase;">${u.role}</span>`;

        return `
            <tr>
                <td style="font-weight:700; color:#0f172a;">
                    ${u.name}
                    ${u.telefono ? `<div style="font-size:0.72rem; font-weight:600; color:#047857; display:flex; align-items:center; gap:4px; margin-top:2px;" title="Teléfono: ${u.telefono}"><i class="fa-solid fa-phone" style="font-size:0.65rem;"></i> ${u.telefono}</div>` : ''}
                </td>
                <td style="text-align:center;">${renglonBadge}</td>
                <td style="text-align:center;">${genderBadge}</td>
                <td style="font-size:0.75rem; color:#475569; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:180px;" title="${u.email || ''}">
                    ${u.email ? u.email : '<span style="color:#94a3b8; font-style:italic;">Sin correo</span>'}
                </td>
                <td>${passCell}</td>
                <td style="text-align:center;">${roleBadge}</td>
                <td style="font-size:0.74rem; color:#475569; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:160px;" title="${u.title || ''}">${u.title || 'Catedrático'}</td>
                <td style="text-align:center; white-space:nowrap;">
                    <div style="display:inline-flex; gap:3px; align-items:center;">
                        <button class="btn btn-primary btn-xs" onclick="impersonateUser('${u.id}')" title="Probar usuario" style="font-size:0.68rem; padding:1px 5px; height:22px; font-weight:700;">
                            <i class="fa-solid fa-user-astronaut"></i> Probar
                        </button>
                        <button class="btn btn-secondary btn-xs" onclick="openEditUserModal('${u.id}')" title="Editar" style="font-size:0.68rem; padding:1px 5px; height:22px;">
                            <i class="fa-solid fa-pen"></i>
                        </button>
                        ${!isMaster ? `<button class="btn btn-secondary btn-xs" style="color:var(--danger); font-size:0.68rem; padding:1px 5px; height:22px;" onclick="deleteUser('${u.id}')" title="Eliminar"><i class="fa-solid fa-trash"></i></button>` : ''}
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}


function toggleUserTableRowPassword(userId) {
    const codeEl = document.getElementById(`userPassCode_${userId}`);
    const iconEl = document.getElementById(`userPassIcon_${userId}`);
    const user = STATE.users.find(u => u.id === userId);
    if (!codeEl || !user) return;

    if (codeEl.dataset.hidden === 'true') {
        codeEl.textContent = user.password || 'C@rolina1';
        codeEl.dataset.hidden = 'false';
        if (iconEl) iconEl.className = 'fa-solid fa-eye-slash';
    } else {
        codeEl.textContent = '••••••••';
        codeEl.dataset.hidden = 'true';
        if (iconEl) iconEl.className = 'fa-solid fa-eye';
    }
}

function printUserCredentialsList() {
    if (STATE.currentRole !== 'admin' && STATE.currentRole !== 'director' && STATE.currentUser?.role !== 'admin') {
        showToast("Acceso Restringido: La exportación de credenciales es exclusiva para Director y Administrador.", "danger");
        return;
    }

    const h = STATE.schoolHeader || getInitialData().schoolHeader;
    const printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Permita las ventanas emergentes para visualizar e imprimir la nómina de credenciales.", "warning");
        return;
    }

    const now = new Date();
    const formattedDate = now.toLocaleDateString('es-GT', { year: 'numeric', month: '2-digit', day: '2-digit' });
    const formattedTime = now.toLocaleTimeString('es-GT', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const teachersCount = STATE.users.filter(u => u.role === 'docente').length;

    printWin.document.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>Nómina de Credenciales - ENCCO 1970</title>
            <style>
                @page { size: 8.5in 13in portrait; margin: 6mm 6mm; }
                body { font-family: 'Segoe UI', Arial, sans-serif; color: #000; margin: 0; padding: 0; background: #fff; font-size: 10.5px; width: 100%; }
                .encc-official-header { border: 1.5px solid #000; margin-bottom: 0px; background: #ffffff; }
                .encc-top-banner { background-color: #99b958 !important; border-bottom: 1.5px solid #000; display: flex; justify-content: space-between; align-items: center; padding: 4px 12px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .encc-top-banner .logo-box { display: flex; align-items: center; gap: 12px; }
                .encc-top-banner img { height: 44px; width: auto; object-fit: contain; }
                .encc-top-banner h1 { margin: 0; font-size: 18px; font-weight: 800; color: #142d14; letter-spacing: 0.2px; }
                .encc-top-banner .bimestre-badge { font-size: 11px; font-weight: 800; color: #142d14; background: #ffffff; padding: 2px 8px; border-radius: 4px; border: 1px solid #142d14; text-transform: uppercase; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .encc-meta-row { display: flex; justify-content: space-between; align-items: stretch; background: #ffffff; }
                .encc-meta-left { padding: 5px 10px; flex: 1; font-size: 11px; line-height: 1.5; display: grid; grid-template-columns: 120px 1fr; row-gap: 2px; }
                .encc-boxes-right { display: flex; border-left: 1.5px solid #000; text-align: center; }
                .encc-box { width: 80px; border-right: 1.5px solid #000; display: flex; flex-direction: column; justify-content: space-between; }
                .encc-box:last-child { border-right: none; }
                .encc-box-num { font-size: 18px; font-weight: 800; color: #000; padding: 2px 0; }
                .encc-box-label { font-size: 9px; font-weight: 700; color: #000; background: #f1f5f9; border-top: 1px solid #000; padding: 2px 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                table.encc-data-table { width: 100%; border-collapse: collapse; font-size: 10px; border: 1.5px solid #000; border-top: none; }
                table.encc-data-table th, table.encc-data-table td { border: 1px solid #000; padding: 4px 6px; }
                table.encc-data-table th { font-weight: 800; background-color: #d9e9f9; color: #0f172a; text-align: center; -webkit-print-color-adjust: exact; print-color-adjust: exact; font-size: 10px; }
                .signatures-box { display: flex; justify-content: space-around; margin-top: 35px; text-align: center; }
                .sig-line { width: 200px; border-top: 1.5px solid #000; padding-top: 4px; font-size: 10.5px; }
                .footer-stamp { margin-top: 12px; display: flex; justify-content: space-between; font-size: 8.5px; color: #475569; }
                @media print { .no-print { display: none; } body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
            </style>
        </head>
        <body>
            <div class="encc-official-header">
                <div class="encc-top-banner">
                    <div class="logo-box">
                        <img src="logo.png" alt="Escudo Oficial" onerror="this.src='https://ui-avatars.com/api/?name=ENCCO&background=15803d&color=fff'">
                        <h1>${h.schoolName || 'Escuela Nacional de Ciencias Comerciales'}</h1>
                    </div>
                    <div class="bimestre-badge">${STATE.config?.activeBimestre || 2}º Bimestre Activo</div>
                </div>
                <div class="encc-meta-row">
                    <div class="encc-meta-left">
                        <strong>Documento:</strong>
                        <span>Nómina de Credenciales y Accesos (Confidencial)</span>
                        <strong>Fecha / Hora:</strong>
                        <span>${formattedDate} a las ${formattedTime}</span>
                        <strong>Ciclo Escolar:</strong>
                        <span>${STATE.activeCycle || '2026'} - Sede Central Jutiapa</span>
                    </div>
                    <div class="encc-boxes-right">
                        <div class="encc-box">
                            <div class="encc-box-num">${(STATE.users || []).length}</div>
                            <div class="encc-box-label">Cuentas</div>
                        </div>
                        <div class="encc-box">
                            <div class="encc-box-num">${teachersCount}</div>
                            <div class="encc-box-label">Docentes</div>
                        </div>
                        <div class="encc-box">
                            <div class="encc-box-num">${(STATE.users || []).length - teachersCount}</div>
                            <div class="encc-box-label">Admin / Dir</div>
                        </div>
                    </div>
                </div>
            </div>

            <table class="encc-data-table">
                <thead>
                    <tr>
                        <th style="width:35px;">No.</th>
                        <th style="text-align:left; padding-left:8px;">Nombre Completo</th>
                        <th style="text-align:left; padding-left:8px;">Correo Electrónico</th>
                        <th style="width:130px; color:#ea580c;">Contraseña de Acceso</th>
                        <th style="width:110px;">Rol / Cargo</th>
                    </tr>
                </thead>
                <tbody>
                    ${STATE.users.map((u, idx) => `
                        <tr>
                            <td style="text-align:center; font-weight:bold; background:#f8fafc;">${idx + 1}</td>
                            <td style="font-weight:700;">${u.name}</td>
                            <td>${u.email ? u.email : '<span style="color:#94a3b8; font-size:0.82rem; font-style:italic;"><i class="fa-regular fa-envelope-open"></i> Sin correo registrado</span>'}</td>
                            <td style="text-align:center; font-weight:800; color:#ea580c; background:#fff7ed;"><code>${u.password || 'C@rolina1'}</code></td>
                            <td style="text-align:center; font-weight:600; text-transform:uppercase; font-size:9.5px;">${u.role}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>

            <div class="footer-stamp">
                <span>Documento Oficial Confidencial - Prohibida su distribución no autorizada</span>
                <span>Generado el: ${formattedDate} ${formattedTime}</span>
            </div>
        </body>
        </html>
    `);
    printWin.document.close();
    setTimeout(() => {
        printWin.focus();
        printWin.print();
    }, 300);
}

function filterUsersTable(val) {
    renderUsersTable(val);
}

// Controladores de Usuario unificados en la sección principal

// ==========================================================================
// 14. UTILIDADES Y CARGA DE VISTAS
