function toggleDashAlertsCard() {
    const list = document.getElementById('dashAnnouncementsList');
    const icon = document.getElementById('toggleAlertsCardIcon');
    const text = document.getElementById('toggleAlertsCardText');
    if (!list) return;

    if (list.style.display === 'none') {
        list.style.display = 'block';
        if (icon) icon.className = 'fa-solid fa-eye-slash';
        if (text) text.textContent = 'Ocultar';
        STATE.hideDashAlertsCard = true;
    } else {
        list.style.display = 'none';
        if (icon) icon.className = 'fa-solid fa-eye';
        if (text) text.textContent = 'Mostrar';
        STATE.hideDashAlertsCard = true;
    }
    saveStateToLocalStorage();
}

