function openGradesDirectoryModal(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (typeof hasRolePermission === 'function' && !hasRolePermission('guide-teachers', STATE.currentRole)) {
        showToast('Acceso Restringido: Su rol no tiene autorización para acceder al Directorio de Maestros Guías.', 'warning');
        return;
    }
    navigateTo('guide-teachers', e);
}
window.openGradesDirectoryModal = openGradesDirectoryModal;

function closeGradesDirectoryModal() {
    hideModalById('gradesDirectoryModal');
}
window.closeGradesDirectoryModal = closeGradesDirectoryModal;

function closeSectionStudentsModal() {
    hideModalById('sectionStudentsModal');
}
window.closeSectionStudentsModal = closeSectionStudentsModal;

function printSectionStudentsList(gradeCode, section) {
    const students = (STATE.students || []).filter(s => (s.gradeCode === gradeCode || s.grade === gradeCode || (s.gradeLabel && s.gradeLabel.includes(gradeCode))) && (!section || s.section === section));
    const gradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode) || { name: gradeCode, section: section || 'A', career: 'Ciclo Diversificado' };

    let rows = students.map((s, idx) => `
        <tr>
            <td style="text-align:center; font-weight:700;">${idx + 1}</td>
            <td><code>${s.carne || '---'}</code></td>
            <td><strong>${s.lastName || ''}, ${s.firstName || s.name || ''}</strong></td>
            <td style="text-align:center;">${s.gender || 'M'}</td>
            <td style="text-align:center;"><span class="badge ${s.status === 'Activo' ? 'badge-success' : 'badge-danger'}">${s.status || 'Activo'}</span></td>
        </tr>
    `).join('');

    if (students.length === 0) {
        rows = `<tr><td colspan="5" style="text-align:center; padding:20px; color:#64748b;">No hay estudiantes matriculados en esta sección.</td></tr>`;
    }

    const html = `
        <div style="font-family:Arial, sans-serif; padding:15px; color:#0f172a;">
            <div style="text-align:center; margin-bottom:14px; border-bottom:2px solid #0369a1; padding-bottom:8px;">
                <h3 style="margin:0; color:#0369a1; text-transform:uppercase;">ESCUELA NACIONAL DE CIENCIAS COMERCIALES</h3>
                <h4 style="margin:2px 0; color:#475569;">ENCCO JUTIAPA - JORNADA MATUTINA</h4>
                <p style="margin:0; font-size:0.85rem; font-weight:700;">NÓMINA OFICIAL DE ESTUDIANTES - CICLO 2026</p>
                <p style="margin:2px 0 0; font-size:0.82rem; color:#64748b;"><strong>Grado y Sección:</strong> ${gradeObj.name} Sección "${gradeObj.section || section}" | <strong>Carrera:</strong> ${gradeObj.career} | <strong>Docente Guía:</strong> ${(typeof getGradeGuideTeacher === 'function' ? getGradeGuideTeacher(gradeObj).name : (gradeObj.guideTeacher || 'Sin asignar'))}</p>
            </div>
            <table style="width:100%; border-collapse:collapse; font-size:0.85rem;">
                <thead>
                    <tr style="background:#0369a1; color:#fff;">
                        <th style="border:1px solid #cbd5e1; padding:6px 8px; width:40px; text-align:center;">No.</th>
                        <th style="border:1px solid #cbd5e1; padding:6px 8px; width:100px;">Carné</th>
                        <th style="border:1px solid #cbd5e1; padding:6px 8px;">Apellidos y Nombres</th>
                        <th style="border:1px solid #cbd5e1; padding:6px 8px; width:70px; text-align:center;">Género</th>
                        <th style="border:1px solid #cbd5e1; padding:6px 8px; width:80px; text-align:center;">Estado</th>
                    </tr>
                </thead>
                <tbody>
                    ${rows}
                </tbody>
            </table>
            <div style="margin-top:20px; display:flex; justify-content:space-between; font-size:0.82rem; color:#64748b; padding-top:10px; border-top:1px dashed #cbd5e1;">
                <span>Total de Estudiantes Matriculados: <strong>${students.length}</strong></span>
                <span>Generado el: ${new Date().toLocaleDateString('es-GT')}</span>
            </div>
        </div>
    `;

    renderAndShowPrintDocument(`Nómina Oficial - ${gradeObj.name} "${gradeObj.section || section}"`, html, 'portrait');
}


