function updateClassAssignmentSelects() {
    const teacherFilter = document.getElementById('assignmentTeacherFilter');
    const gradeFilter = document.getElementById('assignmentGradeFilter');
    const modalTeacherSelect = document.getElementById('classAssignmentTeacherSelect');
    const modalGradeSelect = document.getElementById('classAssignmentGradeSelect');

    const teachers = (STATE.users || []).filter(u => 
        u.role === 'docente' || 
        u.role === 'catedratico' || 
        u.role === 'profesor' || 
        (u.id && u.id.startsWith('usr-doc')) ||
        (u.title && u.title.toLowerCase().includes('docente')) ||
        (u.title && u.title.toLowerCase().includes('catedr'))
    );
    const grades = STATE.gradesList || [];

    if (teacherFilter) {
        const curVal = teacherFilter.value;
        teacherFilter.innerHTML = '<option value="ALL">Todos los Docentes</option>' + teachers.map(t => `<option value="${t.name}">${t.name}</option>`).join('');
        if (curVal && Array.from(teacherFilter.options).some(o => o.value === curVal)) teacherFilter.value = curVal;
    }

    if (gradeFilter) {
        const curVal = gradeFilter.value;
        gradeFilter.innerHTML = '<option value="ALL">Todos los Grados / Secciones</option>' + grades.map(g => `<option value="${g.code}">${g.name} (${g.section})</option>`).join('');
        if (curVal && Array.from(gradeFilter.options).some(o => o.value === curVal)) gradeFilter.value = curVal;
    }

    if (modalTeacherSelect) {
        const curT = modalTeacherSelect.value;
        modalTeacherSelect.innerHTML = '<option value="">-- Seleccionar Docente / Catedrático --</option>' + teachers.map(t => `<option value="${t.id}">${t.name} (${t.title || 'Docente'})</option>`).join('');
        if (curT && Array.from(modalTeacherSelect.options).some(o => o.value === curT)) modalTeacherSelect.value = curT;
    }

    if (modalGradeSelect) {
        const curG = modalGradeSelect.value;
        modalGradeSelect.innerHTML = '<option value="">-- Seleccionar Grado y Sección --</option>' + grades.map(g => `<option value="${g.code}">${g.name} (${g.section}) - ${g.career || 'Perito Contador'}</option>`).join('');
        if (curG && Array.from(modalGradeSelect.options).some(o => o.value === curG)) modalGradeSelect.value = curG;
    }
}


function openClassAssignmentModal() {
    if (!checkEnrolmentPermissions()) return;
    const form = document.querySelector('#classAssignmentModal form');
    if (form) form.reset();

    const idInput = document.getElementById('classAssignmentFormId');
    if (idInput) idInput.value = '';

    const titleEl = document.getElementById('classAssignmentModalTitle');
    if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-chalkboard-user"></i> Asignar Clase a Catedrático';

    const conflictAlert = document.getElementById('classAssignmentConflictAlert');
    if (conflictAlert) conflictAlert.style.display = 'none';

    // 1. Poblar Grados Académicos únicos
    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    const grades = STATE.gradesList || [];
    const uniqueGradeNames = Array.from(new Set(grades.map(g => g.name)));

    if (gradeSelect) {
        gradeSelect.innerHTML = '<option value="">-- Seleccione Grado --</option>' + uniqueGradeNames.map(g => `<option value="${g}">${g}</option>`).join('');
        if (uniqueGradeNames.length > 0) {
            gradeSelect.value = uniqueGradeNames[0];
            onClassAssignmentGradeChange(uniqueGradeNames[0]);
        }
    }

    // 2. Poblar Docentes
    const teacherSelect = document.getElementById('classAssignmentFormTeacher');
    const teachers = (STATE.users || []).filter(u => u.role === 'docente' || u.id.startsWith('usr-doc-'));
    if (teacherSelect) {
        teacherSelect.innerHTML = '<option value="">-- Seleccione Docente --</option>' + teachers.map(t => `<option value="${t.id}">${t.name}</option>`).join('');
    }

    showModalById('classAssignmentModal');
}

function onClassAssignmentGradeChange(gradeName) {
    if (!gradeName) return;

    // 1. Poblar Pills de Secciones seleccionables para este Grado
    const pillsBox = document.getElementById('classAssignmentSectionsPillsContainer');
    const grades = STATE.gradesList || [];
    const matchingSections = grades.filter(g => g.name === gradeName);

    if (pillsBox) {
        if (matchingSections.length === 0) {
            pillsBox.innerHTML = `
                <button type="button" class="asg-section-pill active" data-section="Sección A" data-code="A" onclick="toggleAssignmentSectionPill(this)">
                    <i class="fa-solid fa-circle-check"></i> <span>Sección A</span>
                </button>
            `;
        } else {
            pillsBox.innerHTML = matchingSections.map((g, idx) => `
                <button type="button" class="asg-section-pill ${idx === 0 ? 'active' : ''}" 
                    data-section="${g.section}" data-code="${g.code}" onclick="toggleAssignmentSectionPill(this)">
                    <i class="${idx === 0 ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle'}"></i>
                    <span>${g.section}</span>
                    <small>(${g.code})</small>
                </button>
            `).join('');
        }
    }

    // 2. Poblar Asignaturas del Pensum con sus períodos oficiales dinámicos
    const subjectSelect = document.getElementById('classAssignmentFormSubject');
    const pensumCatalog = STATE.pensumCatalog || [];
    
    // Normalizar coincidencia por grado
    const gLower = gradeName.toLowerCase();
    const matchingSubjects = pensumCatalog.filter(p => {
        const pGrade = (p.grade || '').toLowerCase();
        return (gLower.includes('4to') && pGrade.includes('4to')) ||
               (gLower.includes('5to') && pGrade.includes('5to')) ||
               (gLower.includes('6to') && pGrade.includes('6to')) ||
               (gLower.includes('1ro') && pGrade.includes('1ro')) ||
               (gLower.includes('2do') && pGrade.includes('2do')) ||
               (gLower.includes('3ro') && pGrade.includes('3ro')) ||
               pGrade === gLower;
    });

    const subjectsToDisplay = matchingSubjects.length > 0 ? matchingSubjects : pensumCatalog;

    if (subjectSelect) {
        if (subjectsToDisplay.length === 0) {
            subjectSelect.innerHTML = `
                <option value="Contabilidad General" data-hours="5">Contabilidad General — (5 períodos/sem)</option>
                <option value="Computación" data-hours="3">Computación — (3 períodos/sem)</option>
                <option value="Matemática" data-hours="4">Matemática — (4 períodos/sem)</option>
                <option value="Inglés Técnico" data-hours="3">Inglés Técnico — (3 períodos/sem)</option>
                <option value="Legislación Fiscal" data-hours="4">Legislación Fiscal — (4 períodos/sem)</option>
            `;
        } else {
            subjectSelect.innerHTML = subjectsToDisplay.map(s => {
                const sName = s.name || s.subject || 'Materia';
                const h = s.hours || (sName.toLowerCase().includes('computaci') ? 3 : (sName.toLowerCase().includes('contabil') ? 5 : 4));
                return `<option value="${sName}" data-hours="${h}">${sName} — (${h} períodos/sem)</option>`;
            }).join('');
        }

        // Asignar automáticamente los períodos de la primera materia seleccionada
        onClassAssignmentSubjectChange(subjectSelect);
    }
}

function onClassAssignmentSubjectChange(selectEl) {
    if (!selectEl) return;
    const opt = selectEl.options[selectEl.selectedIndex];
    const hoursInput = document.getElementById('classAssignmentFormHours');
    if (opt) {
        const sName = opt.value || '';
        let hours = opt.dataset.hours;
        if (!hours) {
            if (sName.toLowerCase().includes('computaci') || sName.toLowerCase().includes('inform')) hours = 3;
            else if (sName.toLowerCase().includes('contabil') || sName.toLowerCase().includes('matem')) hours = 5;
            else hours = 4;
        }
        if (hoursInput) hoursInput.value = hours;
    }
    checkClassAssignmentConflict();
}

function toggleAssignmentSectionPill(btn) {
    if (!btn) return;
    const wasActive = btn.classList.contains('active');
    if (wasActive) {
        btn.classList.remove('active');
        const icon = btn.querySelector('i');
        if (icon) icon.className = 'fa-regular fa-circle';
    } else {
        btn.classList.add('active');
        const icon = btn.querySelector('i');
        if (icon) icon.className = 'fa-solid fa-circle-check';
    }
    checkClassAssignmentConflict();
}

function toggleAllAssignmentSections() {
    const pills = document.querySelectorAll('#classAssignmentSectionsPillsContainer .asg-section-pill');
    const allActive = Array.from(pills).every(p => p.classList.contains('active'));
    pills.forEach(p => {
        const icon = p.querySelector('i');
        if (allActive) {
            p.classList.remove('active');
            if (icon) icon.className = 'fa-regular fa-circle';
        } else {
            p.classList.add('active');
            if (icon) icon.className = 'fa-solid fa-circle-check';
        }
    });
    checkClassAssignmentConflict();
}

function checkClassAssignmentConflict() {
    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    const subjectSelect = document.getElementById('classAssignmentFormSubject');
    const teacherSelect = document.getElementById('classAssignmentFormTeacher');
    const alertBox = document.getElementById('classAssignmentConflictAlert');
    const alertText = document.getElementById('classAssignmentConflictText');

    if (!gradeSelect || !subjectSelect || !alertBox || !alertText) return;

    const gradeName = gradeSelect.value;
    const subject = subjectSelect.value;
    const teacherId = teacherSelect ? teacherSelect.value : '';

    const activePills = document.querySelectorAll('#classAssignmentSectionsPillsContainer .asg-section-pill.active');
    const selectedSections = Array.from(activePills).map(p => p.dataset.section || p.textContent.trim());

    if (!gradeName || !subject || selectedSections.length === 0) {
        alertBox.style.display = 'none';
        return;
    }

    const currentId = document.getElementById('classAssignmentFormId')?.value;
    const conflicts = [];

    selectedSections.forEach(sec => {
        const existing = (STATE.pensum || []).find(a => 
            a.id !== currentId &&
            a.grade === gradeName &&
            a.section === sec &&
            ((a.subject || a.name || '').toLowerCase() === subject.toLowerCase())
        );

        if (existing && existing.teacherId !== teacherId) {
            conflicts.push(`<strong>${sec}</strong> (actualmente con <em>${existing.teacher || 'otro docente'}</em>)`);
        }
    });

    if (conflicts.length > 0) {
        alertBox.style.display = 'block';
        alertText.innerHTML = `<strong>⚠️ Aviso de Reasignación:</strong> La asignatura <strong>"${subject}"</strong> ya tiene catedrático en: ${conflicts.join(', ')}.<br>Al guardar, la clase será transferida y asignada al nuevo catedrático seleccionado.`;
    } else {
        alertBox.style.display = 'none';
    }
}

// Bloque heredado reemplazado por controlador moderno de asignaciones

function filterAssignmentsTable(searchQuery = '') {
    renderAssignmentsTable(searchQuery);
}

function renderAssignmentsTable(searchQuery = '') {
    const tbody = document.getElementById('assignmentsTableBody');
    if (!tbody) return;

    const rutaColeccion = 'pensum';
    console.log("Consultando asignaciones en ruta:", rutaColeccion);
    if ((!STATE.pensum || STATE.pensum.length === 0) && typeof loadPensumFromCloudFallback === 'function') {
        loadPensumFromCloudFallback();
    }

    if (typeof updateClassAssignmentSelects === 'function') {
        updateClassAssignmentSelects();
    }

    const teacherFilter = (document.getElementById('assignmentTeacherFilter')?.value || 'ALL');
    const gradeFilter = (document.getElementById('assignmentGradeFilter')?.value || 'ALL');
    const q = (typeof searchQuery === 'string' ? searchQuery : (document.getElementById('assignmentSearchInput')?.value || '')).toLowerCase().trim();

    let list = Array.isArray(STATE.pensum) && STATE.pensum.length > 0
        ? [...STATE.pensum]
        : (typeof getInitialData === 'function' && Array.isArray(getInitialData().pensum) ? [...getInitialData().pensum] : []);

    if (teacherFilter && teacherFilter !== 'ALL') {
        const targetUser = (STATE.users || []).find(u => u.name === teacherFilter || u.id === teacherFilter) || { name: teacherFilter, id: teacherFilter };
        list = list.filter(a => {
            if (typeof isCourseAssignedToTeacher === 'function') {
                return isCourseAssignedToTeacher(a, targetUser);
            }
            if (a.teacherId && targetUser.id && a.teacherId === targetUser.id) return true;
            if (a.teacher && targetUser.name) {
                const normA = a.teacher.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                const normT = targetUser.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                return normA.includes(normT) || normT.includes(normA);
            }
            return false;
        });
    }

    if (gradeFilter && gradeFilter !== 'ALL') {
        list = list.filter(a => 
            a.gradeCode === gradeFilter || 
            `${a.grade} (${a.section})` === gradeFilter ||
            `${a.grade} ${a.section}` === gradeFilter ||
            (a.section && a.grade && `${a.grade} (${a.section})`.toLowerCase() === gradeFilter.toLowerCase()) ||
            (a.gradeCode && a.gradeCode.toLowerCase() === gradeFilter.toLowerCase())
        );
    }

    if (q) {
        const normQ = q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        list = list.filter(a => {
            const raw = `${a.teacher || ''} ${a.subject || a.name || a.subjectName || ''} ${a.grade || ''} ${a.section || ''} ${a.gradeCode || ''} ${a.career || ''}`.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
            return raw.includes(normQ);
        });
    }

    if (list.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="6" style="text-align:center; padding:35px; color:var(--text-muted);">
                    <i class="fa-solid fa-chalkboard-user" style="font-size:2.2rem; margin-bottom:10px; display:block; color:var(--brand-green);"></i>
                    <strong>No hay asignaciones de cátedras que coincidan con los filtros.</strong><br>
                    <span style="font-size:0.85rem;">Haga clic en <strong>"+ Asignar Clase a Docente"</strong> para crear una nueva asignación de materia a un catedrático.</span>
                </td>
            </tr>
        `;
        return;
    }
    tbody.innerHTML = list.map(a => {
        const rawG = `${a.grade || ''} ${a.gradeCode || ''}`.toUpperCase();
        let gGradeNum = 0;
        if (rawG.includes('6') || rawG.includes('SEXTO') || rawG.includes('6TO')) gGradeNum = 6;
        else if (rawG.includes('5') || rawG.includes('QUINTO') || rawG.includes('5TO')) gGradeNum = 5;
        else if (rawG.includes('4') || rawG.includes('CUARTO') || rawG.includes('4TO')) gGradeNum = 4;

        const subName = getFullOfficialSubjectName(a.subject || a.name || 'Asignatura', gGradeNum);
        return `
        <tr>
            <td><span class="badge badge-info" style="font-weight:700;">${a.career || 'Perito Contador'}</span></td>
            <td><strong>${a.grade || a.gradeCode} (${a.section || 'A'})</strong></td>
            <td>
                ${a.code ? `<span class="badge" style="font-family:'Courier New',Courier,monospace; font-size:0.75rem; background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; margin-right:5px; font-weight:800;"><i class="fa-solid fa-barcode" style="font-size:0.7rem; margin-right:3px;"></i>${a.code}</span>` : ''}
                <strong style="color:var(--brand-green-dark); font-size:0.95rem;">${subName}</strong>
            </td>
            <td><strong style="color:var(--text-primary);"><i class="fa-solid fa-user-tie" style="color:var(--brand-green); margin-right:4px;"></i> ${(typeof getTeacherOfficialName === 'function') ? getTeacherOfficialName(a) : (a.teacher || a.teacherName || 'Sin asignar')}</strong></td>
            <td style="text-align:center; font-weight:700;">${a.periodsPerWeek || a.hours || a.periods || 4} períodos/sem</td>
            <td style="text-align:center; white-space:nowrap;">
                <button type="button" class="btn btn-sm btn-outline-primary" onclick="openEditClassAssignmentModal('${a.id}')" title="Editar asignación" style="padding:3px 8px; margin-right:4px;"><i class="fa-solid fa-pen-to-square"></i></button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteClassAssignment('${a.id}')" title="Eliminar asignación" style="padding:3px 8px;"><i class="fa-solid fa-trash"></i></button>
            </td>
        </tr>
        `;
    }).join('');
}

// ==========================================================================
// 🎛️ CONTROLADOR INTEGRAL DE ASIGNACIONES DE CLASES A DOCENTES
// ==========================================================================

function updateAssignmentSelects() {
    updateClassAssignmentSelects();
}

function updateClassAssignmentSelects() {
    const teacherFilter = document.getElementById('assignmentTeacherFilter');
    const gradeFilter = document.getElementById('assignmentGradeFilter');
    const modalGradeSelect = document.getElementById('classAssignmentFormGrade');
    const modalTeacherSelect = document.getElementById('classAssignmentFormTeacher');

    const teachers = (STATE.users || []).filter(u => 
        u.role === 'docente' || 
        u.role === 'catedratico' || 
        u.role === 'profesor' || 
        (u.id && u.id.startsWith('usr-doc')) ||
        (u.title && u.title.toLowerCase().includes('docente')) ||
        (u.title && u.title.toLowerCase().includes('catedr'))
    );
    const grades = STATE.gradesList || [];

    if (teacherFilter) {
        const curVal = teacherFilter.value;
        teacherFilter.innerHTML = '<option value="ALL">Todos los Docentes</option>' + teachers.map(t => `<option value="${t.name}">${t.name}</option>`).join('');
        if (curVal && Array.from(teacherFilter.options).some(o => o.value === curVal)) teacherFilter.value = curVal;
        else teacherFilter.value = 'ALL';
    }

    if (gradeFilter) {
        const curVal = gradeFilter.value;
        gradeFilter.innerHTML = '<option value="ALL">Todos los Grados / Secciones</option>' + grades.map(g => `<option value="${g.code}">${g.name} (${g.section})</option>`).join('');
        if (curVal && Array.from(gradeFilter.options).some(o => o.value === curVal)) gradeFilter.value = curVal;
        else gradeFilter.value = 'ALL';
    }

    if (modalGradeSelect) {
        const curG = modalGradeSelect.value;
        const uniqueGrades = Array.from(new Set(grades.map(g => g.name)));
        modalGradeSelect.innerHTML = '<option value="">-- Seleccione Grado --</option>' + uniqueGrades.map(gName => `<option value="${gName}">${gName}</option>`).join('');
        if (curG && Array.from(modalGradeSelect.options).some(o => o.value === curG)) {
            modalGradeSelect.value = curG;
        } else if (uniqueGrades.length > 0) {
            modalGradeSelect.value = uniqueGrades[0];
            onClassAssignmentGradeChange(uniqueGrades[0]);
        }
    }

    if (modalTeacherSelect) {
        const curT = modalTeacherSelect.value;
        modalTeacherSelect.innerHTML = '<option value="">-- Seleccione Catedrático Titular --</option>' + teachers.map(t => `<option value="${t.id}">${t.name} (${t.title || 'Docente'})</option>`).join('');
        if (curT && Array.from(modalTeacherSelect.options).some(o => o.value === curT)) modalTeacherSelect.value = curT;
    }
}

function openClassAssignmentModal() {
    if (!checkEnrolmentPermissions()) return;
    const form = document.querySelector('#classAssignmentModal form');
    if (form) form.reset();

    const idInput = document.getElementById('classAssignmentFormId');
    if (idInput) idInput.value = '';

    const titleEl = document.getElementById('classAssignmentModalTitle');
    if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-chalkboard-user"></i> Asignar Clase a Catedrático';

    const conflictAlert = document.getElementById('classAssignmentConflictAlert');
    if (conflictAlert) conflictAlert.style.display = 'none';

    updateClassAssignmentSelects();

    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    if (gradeSelect && gradeSelect.value) {
        onClassAssignmentGradeChange(gradeSelect.value);
    }

    showModalById('classAssignmentModal');
}

function closeClassAssignmentModal() {
    const modal = document.getElementById('classAssignmentModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function onClassAssignmentGradeChange(gradeName) {
    if (!gradeName) return;

    // 1. Poblar Secciones (Pills)
    const pillsBox = document.getElementById('classAssignmentSectionsPillsContainer');
    const grades = STATE.gradesList || [];
    const matchingSections = grades.filter(g => g.name === gradeName);

    if (pillsBox) {
        if (matchingSections.length === 0) {
            pillsBox.innerHTML = `
                <button type="button" class="asg-section-pill active" data-section="Sección A" data-code="A" onclick="toggleAssignmentSectionPill(this)">
                    <i class="fa-solid fa-circle-check"></i> <span>Sección A</span>
                </button>
            `;
        } else {
            pillsBox.innerHTML = matchingSections.map((g, idx) => `
                <button type="button" class="asg-section-pill ${idx === 0 ? 'active' : ''}" 
                    data-section="${g.section}" data-code="${g.code}" onclick="toggleAssignmentSectionPill(this)">
                    <i class="${idx === 0 ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle'}"></i>
                    <span>${g.section}</span>
                    <small>(${g.code})</small>
                </button>
            `).join('');
        }
    }

    // 2. Poblar Asignaturas del Pensum
    const subjectSelect = document.getElementById('classAssignmentFormSubject');
    const pensumCatalog = STATE.pensumCatalog || [];
    const gLower = gradeName.toLowerCase();

    const matchingSubjects = pensumCatalog.filter(p => {
        const pGrade = (p.grade || '').toLowerCase();
        return (gLower.includes('4to') && pGrade.includes('4to')) ||
               (gLower.includes('5to') && pGrade.includes('5to')) ||
               (gLower.includes('6to') && pGrade.includes('6to')) ||
               (pGrade === gLower);
    });

    const subjectsToDisplay = matchingSubjects.length > 0 ? matchingSubjects : pensumCatalog;

    if (subjectSelect) {
        if (subjectsToDisplay.length === 0) {
            subjectSelect.innerHTML = '<option value="">-- Sin materias en pensum para este grado --</option>';
        } else {
            subjectSelect.innerHTML = '<option value="">-- Seleccione Asignatura del Pensum --</option>' + subjectsToDisplay.map(s => {
                const sName = s.name || s.subject;
                const hours = s.periods || s.hours || 4;
                const codeBadge = s.code ? `[${s.code}] ` : '';
                return `<option value="${sName}" data-code="${s.code || ''}" data-hours="${hours}">${codeBadge}${sName} • (${hours} períodos/sem)</option>`;
            }).join('');
        }
    }
}

function toggleAssignmentSectionPill(pillBtn) {
    if (!pillBtn) return;
    const isActive = pillBtn.classList.contains('active');
    if (isActive) {
        pillBtn.classList.remove('active');
        const icon = pillBtn.querySelector('i');
        if (icon) {
            icon.className = 'fa-regular fa-circle';
        }
    } else {
        pillBtn.classList.add('active');
        const icon = pillBtn.querySelector('i');
        if (icon) {
            icon.className = 'fa-solid fa-circle-check';
        }
    }
}

function toggleAllAssignmentSections() {
    const pills = document.querySelectorAll('#classAssignmentSectionsPillsContainer .asg-section-pill');
    if (pills.length === 0) return;
    const allActive = Array.from(pills).every(p => p.classList.contains('active'));
    pills.forEach(p => {
        if (allActive) {
            p.classList.remove('active');
            const icon = p.querySelector('i');
            if (icon) icon.className = 'fa-regular fa-circle';
        } else {
            p.classList.add('active');
            const icon = p.querySelector('i');
            if (icon) icon.className = 'fa-solid fa-circle-check';
        }
    });
}

async function saveClassAssignmentForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    if (!checkEnrolmentPermissions()) return;

    const idInput = document.getElementById('classAssignmentFormId');
    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    const subjectSelect = document.getElementById('classAssignmentFormSubject');
    const teacherSelect = document.getElementById('classAssignmentFormTeacher');
    const hoursInput = document.getElementById('classAssignmentFormHours') || document.getElementById('classAssignmentFormPeriods');

    const id = idInput ? idInput.value : '';
    const gradeName = gradeSelect ? gradeSelect.value : '';
    const rawSub = subjectSelect ? subjectSelect.value : '';
    const teacherId = teacherSelect ? teacherSelect.value : '';
    const periods = hoursInput ? parseInt(hoursInput.value) || 4 : 4;

    const activePills = document.querySelectorAll('#classAssignmentSectionsPillsContainer .asg-section-pill.active');
    const selectedSections = Array.from(activePills).map(p => ({
        section: p.dataset.section || p.textContent.trim(),
        code: p.dataset.code || `${gradeName} ${p.dataset.section || p.textContent.trim()}`
    }));

    if (!gradeName || !rawSub || !teacherId) {
        showToast('Complete el grado, asignatura y docente a asignar.', 'warning');
        return;
    }

    if (selectedSections.length === 0) {
        showToast('Debe seleccionar al menos una sección haciendo clic en su botón.', 'warning');
        return;
    }

    // 🚨 2. Verificación de Referencia e ID de Documento en modo edición
    const titleEl = document.getElementById('classAssignmentModalTitle');
    const isEditing = Boolean(id) || (titleEl && titleEl.textContent && titleEl.textContent.includes('Editar'));
    if (isEditing) {
        if (!id || id === 'undefined' || id === 'null') {
            console.error("Error: ID de la asignación no encontrado o indefinido.");
            showToast("Error: ID de la asignación no encontrado o indefinido.", "danger");
            return;
        }
    }

    const teacher = (STATE.users || []).find(u => u.id === teacherId);
    const teacherName = teacher ? teacher.name : 'Catedrático Titular';

    const rawG = gradeName.toUpperCase();
    let gGradeNum = 0;
    if (rawG.includes('6') || rawG.includes('SEXTO') || rawG.includes('6TO')) gGradeNum = 6;
    else if (rawG.includes('5') || rawG.includes('QUINTO') || rawG.includes('5TO')) gGradeNum = 5;
    else if (rawG.includes('4') || rawG.includes('CUARTO') || rawG.includes('4TO')) gGradeNum = 4;

    const fullSubjectName = getFullOfficialSubjectName(rawSub, gGradeNum);

    const targetCatalogMatch = (STATE.pensumCatalog || []).find(p => 
        (p.name?.toLowerCase() === fullSubjectName.toLowerCase() || p.subject?.toLowerCase() === fullSubjectName.toLowerCase() ||
         fullSubjectName.toLowerCase().includes(p.name?.toLowerCase() || '---') || (p.name && p.name.toLowerCase().includes(rawSub.toLowerCase()))) &&
        (p.grade?.toLowerCase().includes(String(gGradeNum)) || p.gradeCode?.toLowerCase().includes(String(gGradeNum)))
    );
    const assignedCourseCode = targetCatalogMatch?.code || '';

    if (!Array.isArray(STATE.pensum)) STATE.pensum = [];

    const submitBtn = document.getElementById('classAssignmentSubmitBtn') || document.querySelector('#classAssignmentModal form button[type="submit"]');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : 'Guardar Asignación';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        if (id) {
            const a = STATE.pensum.find(x => x.id === id);
            if (a) {
                a.teacherId = teacherId;
                a.teacher = teacherName;
                a.grade = gradeName;
                a.gradeCode = selectedSections[0].code;
                a.section = selectedSections[0].section;
                a.subject = fullSubjectName;
                a.name = fullSubjectName;
                a.periodsPerWeek = periods;
                a.hours = periods;
                if (assignedCourseCode) a.code = assignedCourseCode;
            }
        } else {
            selectedSections.forEach(sec => {
                const existingIdx = STATE.pensum.findIndex(x => 
                    (x.grade === gradeName || x.gradeCode === sec.code) &&
                    x.section === sec.section &&
                    getFullOfficialSubjectName(x.subject || x.name, gGradeNum) === fullSubjectName
                );

                if (existingIdx !== -1) {
                    STATE.pensum[existingIdx].teacherId = teacherId;
                    STATE.pensum[existingIdx].teacher = teacherName;
                    STATE.pensum[existingIdx].periodsPerWeek = periods;
                    STATE.pensum[existingIdx].hours = periods;
                    STATE.pensum[existingIdx].subject = fullSubjectName;
                    STATE.pensum[existingIdx].name = fullSubjectName;
                    if (assignedCourseCode) STATE.pensum[existingIdx].code = assignedCourseCode;
                } else {
                    STATE.pensum.push({
                        id: 'asg-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
                        code: assignedCourseCode,
                        teacherId: teacherId,
                        teacher: teacherName,
                        grade: gradeName,
                        gradeCode: sec.code,
                        section: sec.section,
                        subject: fullSubjectName,
                        name: fullSubjectName,
                        career: 'Perito Contador',
                        periodsPerWeek: periods,
                        hours: periods
                    });
                }
            });
        }

        const nowTime = Date.now();
        const rutaColeccion = 'pensum';
        console.log("Consultando asignaciones en ruta:", rutaColeccion);
        // 🌟 A. Persistencia Atómica en Firestore (colección pensum con merge: true)
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
                const relevantAssignments = id ? [STATE.pensum.find(x => x.id === id)].filter(Boolean) : STATE.pensum.slice(-selectedSections.length);
                for (const asg of relevantAssignments) {
                    if (asg && asg.id) {
                        const asgRef = doc(db, 'pensum', asg.id);
                        const asgData = { ...asg, lastModified: nowTime };
                        const fsAction = (typeof setDoc === 'function')
                    ? setDoc(asgRef, asgData, { merge: true })
                    : ((typeof updateDoc === 'function')
                        ? updateDoc(asgRef, asgData).catch(e => {
                            if (typeof setDoc === 'function') return setDoc(asgRef, asgData, { merge: true });
                            throw e;
                        })
                        : Promise.resolve());
                        await withTimeout(fsAction, 8000, 'Tiempo de espera en Firestore agotado.');
                    }
                }
            } catch(fsErr) {
                console.warn("Aviso al guardar asignación en Firestore:", fsErr);
            }
        }

        // 🌟 B. Sincronización atómica aislada en Realtime Database
        let ok = false;
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            ok = await withTimeout(EnccoCloudSync.syncNode('pensum', STATE.pensum), 8000, 'Tiempo de espera agotado en Realtime Database.');
        } else {
            ok = true;
        }

        if (!ok) {
            throw new Error("El servidor de Firebase no confirmó la asignación de clase.");
        }

        saveStateToLocalStorage();
        closeClassAssignmentModal();

        // Actualización reactiva
        renderAssignmentsTable();
        if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
        if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
        if (typeof renderUsersTable === 'function') renderUsersTable();

        showToast(`Asignación de "${fullSubjectName}" a ${teacherName} confirmada en Firebase.`, 'success');
    } catch(err) {
        console.error("❌ Error al guardar asignación en Firebase:", err);
        showToast(`Error al guardar en Firebase: ${err.message || err}`, 'danger');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml;
        }
    }
}

function openEditClassAssignmentModal(asgId) {
    if (!checkEnrolmentPermissions()) return;
    const a = (STATE.pensum || []).find(x => x.id === asgId);
    if (!a) return;

    openClassAssignmentModal();

    const titleEl = document.getElementById('classAssignmentModalTitle');
    if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-pen-to-square"></i> Editar Asignación de Clase';

    document.getElementById('classAssignmentFormId').value = a.id;

    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    if (gradeSelect) {
        gradeSelect.value = a.grade;
        onClassAssignmentGradeChange(a.grade);
        // Activar la píldora exacta de la sección de la cátedra a editar
        if (a.section || a.gradeCode) {
            const secTarget = (a.section || a.gradeCode).trim();
            const pills = document.querySelectorAll('#classAssignmentSectionsPillsContainer .asg-section-pill');
            let matchedPill = false;
            pills.forEach(p => {
                const pSec = (p.dataset.section || p.textContent || '').trim();
                const pCode = (p.dataset.code || '').trim();
                if (pSec === secTarget || pCode === secTarget || pSec.includes(secTarget) || secTarget.includes(pSec)) {
                    p.classList.add('active');
                    const icon = p.querySelector('i');
                    if (icon) icon.className = 'fa-solid fa-circle-check';
                    matchedPill = true;
                } else {
                    p.classList.remove('active');
                    const icon = p.querySelector('i');
                    if (icon) icon.className = 'fa-regular fa-circle';
                }
            });
            if (!matchedPill && pills.length > 0) {
                pills[0].classList.add('active');
                const icon = pills[0].querySelector('i');
                if (icon) icon.className = 'fa-solid fa-circle-check';
            }
        }
    }

    const teacherSelect = document.getElementById('classAssignmentFormTeacher');
    if (teacherSelect && a.teacherId) {
        teacherSelect.value = a.teacherId;
    }

    const subjectSelect = document.getElementById('classAssignmentFormSubject');
    if (subjectSelect) {
        subjectSelect.value = a.subject || a.name;
    }

    const hoursInput = document.getElementById('classAssignmentFormHours') || document.getElementById('classAssignmentFormPeriods');
    if (hoursInput) {
        hoursInput.value = a.periodsPerWeek || a.hours || 4;
    }
}

async function deleteClassAssignment(asgId) {
    if (!checkEnrolmentPermissions()) return;
    const rutaColeccion = 'pensum';
    console.log("Consultando asignaciones en ruta:", rutaColeccion);
    const a = (STATE.pensum || []).find(x => x.id === asgId);
    if (!a) return;

    if (!confirm(`¿Está seguro de eliminar la asignación de la clase "${a.subject || a.name}" al docente ${a.teacher}?`)) return;

    const prevPensum = [...STATE.pensum];
    STATE.pensum = (STATE.pensum || []).filter(x => x.id !== asgId);

    try {
        // 🌟 A. Borrado Atómico en Firestore (colección pensum)
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, deleteDoc } = window.FirebaseModular;
                if (typeof deleteDoc === 'function') {
                    await deleteDoc(doc(db, 'pensum', asgId));
                }
            } catch(fsErr) {
                console.warn("Aviso al eliminar cátedra en Firestore:", fsErr);
            }
        }

        // 🌟 B. Sincronización atómica aislada en Realtime Database
        let ok = false;
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            ok = await EnccoCloudSync.syncNode('pensum', STATE.pensum);
        } else {
            ok = true;
        }

        if (!ok) throw new Error("Firebase no confirmó la eliminación de la cátedra.");

        saveStateToLocalStorage();
        renderAssignmentsTable();
        if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
        if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
        showToast('Asignación de cátedra eliminada y confirmada en Firebase.', 'success');
    } catch(err) {
        STATE.pensum = prevPensum;
        console.error("❌ Error al eliminar asignación en Firebase:", err);
        showToast(`Error al eliminar en Firebase: ${err.message || err}`, 'danger');
    }
}

function filterAssignmentsTable(searchQuery = '') {
    renderAssignmentsTable(searchQuery);
}

function renderAssignmentsTable(searchQuery = '') {
    const tbody = document.getElementById('assignmentsTableBody');
    if (!tbody) return;

    const rutaColeccion = 'pensum';
    console.log("Consultando asignaciones en ruta:", rutaColeccion);
    if ((!STATE.pensum || STATE.pensum.length === 0) && typeof loadPensumFromCloudFallback === 'function') {
        loadPensumFromCloudFallback();
    }

    if (typeof updateClassAssignmentSelects === 'function') {
        updateClassAssignmentSelects();
    }

    const teacherFilter = (document.getElementById('assignmentTeacherFilter')?.value || 'ALL');
    const gradeFilter = (document.getElementById('assignmentGradeFilter')?.value || 'ALL');
    const q = (typeof searchQuery === 'string' ? searchQuery : (document.getElementById('assignmentSearchInput')?.value || '')).toLowerCase().trim();

    let list = Array.isArray(STATE.pensum) && STATE.pensum.length > 0
        ? [...STATE.pensum]
        : (typeof getInitialData === 'function' && Array.isArray(getInitialData().pensum) ? [...getInitialData().pensum] : []);

    if (teacherFilter && teacherFilter !== 'ALL') {
        const targetUser = (STATE.users || []).find(u => u.name === teacherFilter || u.id === teacherFilter) || { name: teacherFilter, id: teacherFilter };
        list = list.filter(a => {
            if (typeof isCourseAssignedToTeacher === 'function') {
                return isCourseAssignedToTeacher(a, targetUser);
            }
            if (a.teacherId && targetUser.id && a.teacherId === targetUser.id) return true;
            if (a.teacher && targetUser.name) {
                const normA = a.teacher.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                const normT = targetUser.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                return normA.includes(normT) || normT.includes(normA);
            }
            return false;
        });
    }

    if (gradeFilter && gradeFilter !== 'ALL') {
        list = list.filter(a => 
            a.gradeCode === gradeFilter || 
            `${a.grade} (${a.section})` === gradeFilter ||
            `${a.grade} ${a.section}` === gradeFilter ||
            (a.section && a.grade && `${a.grade} (${a.section})`.toLowerCase() === gradeFilter.toLowerCase()) ||
            (a.gradeCode && a.gradeCode.toLowerCase() === gradeFilter.toLowerCase())
        );
    }

    if (q) {
        const normQ = q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        list = list.filter(a => {
            const raw = `${a.teacher || ''} ${a.subject || a.name || a.subjectName || ''} ${a.grade || ''} ${a.section || ''} ${a.gradeCode || ''} ${a.career || ''}`.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
            return raw.includes(normQ);
        });
    }

    if (list.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="6" style="text-align:center; padding:35px; color:var(--text-muted);">
                    <i class="fa-solid fa-chalkboard-user" style="font-size:2.2rem; margin-bottom:10px; display:block; color:var(--brand-green);"></i>
                    <strong>No hay asignaciones de cátedras que coincidan con los filtros.</strong><br>
                    <span style="font-size:0.85rem;">Haga clic en <strong>"+ Asignar Clase a Docente"</strong> para crear una nueva asignación de materia a un catedrático.</span>
                </td>
            </tr>
        `;
        return;
    }
    tbody.innerHTML = list.map(a => {
        const rawG = `${a.grade || ''} ${a.gradeCode || ''}`.toUpperCase();
        let gGradeNum = 0;
        if (rawG.includes('6') || rawG.includes('SEXTO') || rawG.includes('6TO')) gGradeNum = 6;
        else if (rawG.includes('5') || rawG.includes('QUINTO') || rawG.includes('5TO')) gGradeNum = 5;
        else if (rawG.includes('4') || rawG.includes('CUARTO') || rawG.includes('4TO')) gGradeNum = 4;

        const subName = getFullOfficialSubjectName(a.subject || a.name || 'Asignatura', gGradeNum);
        return `
        <tr>
            <td><span class="badge badge-info" style="font-weight:700;">${a.career || 'Perito Contador'}</span></td>
            <td><strong>${a.grade || a.gradeCode} (${a.section || 'A'})</strong></td>
            <td><strong style="color:var(--brand-green-dark); font-size:0.95rem;">${subName}</strong></td>
            <td><strong style="color:var(--text-primary);"><i class="fa-solid fa-user-tie" style="color:var(--brand-green); margin-right:4px;"></i> ${(typeof getTeacherOfficialName === 'function') ? getTeacherOfficialName(a) : (a.teacher || a.teacherName || 'Sin asignar')}</strong></td>
            <td style="text-align:center; font-weight:700;">${a.periodsPerWeek || a.hours || a.periods || 4} períodos/sem</td>
            <td style="text-align:center; white-space:nowrap;">
                <button type="button" class="btn btn-sm btn-outline-primary" onclick="openEditClassAssignmentModal('${a.id}')" title="Editar asignación" style="padding:3px 8px; margin-right:4px;"><i class="fa-solid fa-pen-to-square"></i></button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteClassAssignment('${a.id}')" title="Eliminar asignación" style="padding:3px 8px;"><i class="fa-solid fa-trash"></i></button>
            </td>
        </tr>
        `;
    }).join('');
}
