// ======================================================================
// ⚡ ESCUCHADORES BIDIRECCIONALES FIRESTORE ON-SNAPSHOT (EN MEMORIA RAM)
// ======================================================================
let _firestoreModularUnsubscribers = [];
function initFirestoreModularLiveListeners() {
    if (typeof _firestoreModularUnsubscribers !== 'undefined' && _firestoreModularUnsubscribers.length > 0) {
        console.log(`⚡ [Firestore] Limpiando ${_firestoreModularUnsubscribers.length} listeners previos para evitar duplicados.`);
        _firestoreModularUnsubscribers.forEach(unsub => { try { unsub(); } catch(e) {} });
        _firestoreModularUnsubscribers = [];
    }

    if (typeof window === 'undefined') return;
    if (!window.FirebaseModular || !window.FirebaseModular.db) return;

    try {
        const { app, db, collection, doc, onSnapshot, setDoc } = window.FirebaseModular;
        console.log("⚡ [Firestore onSnapshot] Activando sincronización bidireccional en tiempo real para Usuarios, Calificaciones, Roles y Maestros Guías...");

        // 🔐 Configurar persistencia de autenticación por sesión de navegador ('browserSessionPersistence')
        if (app && !window.FirebaseModular.auth) {
            try {
                import("https://www.gstatic.com/firebasejs/10.13.0/firebase-auth.js").then(async authMod => {
                    const auth = authMod.getAuth(app);
                    if (authMod.browserSessionPersistence) {
                        await authMod.setPersistence(auth, authMod.browserSessionPersistence).catch(e => {
                            console.warn("Aviso setPersistence en Auth:", e);
                        });
                    }
                    window.FirebaseModular.auth = auth;
                    window.FirebaseModular.authMod = authMod;
                    window.FirebaseModular.signOut = authMod.signOut;
                    window.FirebaseModular.browserSessionPersistence = authMod.browserSessionPersistence;
                    console.log("🔐 [Firebase Auth] browserSessionPersistence configurado exitosamente en sesión de navegador.");
                }).catch(e => {
                    console.warn("Aviso al cargar Firebase Auth Modular:", e);
                });
            } catch(e) {}
        }

        // 1. 👥 ESCUCHAR USUARIOS Y DOCENTES ('users' y 'docentes') EN TIEMPO REAL
        try {
            const unsubUsers = onSnapshot(collection(db, 'users'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales

                snap.docChanges().forEach(change => {
                    const data = change.doc.data();
                    const uId = change.doc.id;
                    const fullObj = { id: uId, ...data };

                    if (change.type === 'added' || change.type === 'modified') {
                        const idx = (STATE.users || []).findIndex(u => u.id === uId);
                        if (idx !== -1) {
                            STATE.users[idx] = { ...STATE.users[idx], ...fullObj };
                        } else {
                            if (!STATE.users) STATE.users = [];
                            STATE.users.push(fullObj);
                        }

                        // ⚡ Si el usuario modificado es el usuario actualmente logueado, actualizar rol/datos inmediatamente sin recargar
                        if (STATE.currentUser && (STATE.currentUser.id === uId || STATE.currentUser.username === fullObj.username)) {
                            const oldRole = STATE.currentRole;
                            STATE.currentUser = { ...STATE.currentUser, ...fullObj };
                            if (fullObj.role && fullObj.role !== oldRole) {
                                STATE.currentRole = fullObj.role;
                                if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole);
                                if (typeof showToast === 'function') {
                                    showToast(`⚡ Su rol ha sido actualizado a ${STATE.currentRole.toUpperCase()} por el Administrador.`, 'info');
                                }
                            }
                        }
                    } else if (change.type === 'removed') {
                        const idx = (STATE.users || []).findIndex(u => u.id === uId);
                        if (idx !== -1) {
                            STATE.users.splice(idx, 1);
                        }
                    }
                });

                if (typeof renderUsersTable === 'function') renderUsersTable();
                if (typeof updateTopRoleBar === 'function') updateTopRoleBar();
                if (typeof updateLoginAccountSelect === 'function') updateLoginAccountSelect();
                if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();
                if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
                if (typeof renderCurrentView === 'function' && STATE.activeView === 'users') renderCurrentView();
            }, err => console.warn('Aviso en onSnapshot users:', err));
            if (typeof unsubUsers === 'function') _firestoreModularUnsubscribers.push(unsubUsers);
        } catch(e) {}

        // Escuchar colección complementaria 'docentes' (con protección de rol)
        try {
            const unsubDocentes = onSnapshot(collection(db, 'docentes'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales
                snap.forEach(d => {
                    const data = d.data();
                    const idx = (STATE.users || []).findIndex(u => u.id === d.id);
                    if (idx !== -1) {
                        const currentRole = STATE.users[idx].role;
                        // Si el usuario en STATE ya tiene un rol distinto a 'docente' (ej: secretaria, admin, director),
                        // NUNCA revertir su rol al valor obsoleto de la colección docentes
                        if (currentRole && currentRole !== 'docente') {
                            const { role, ...otherData } = data;
                            STATE.users[idx] = { ...STATE.users[idx], ...otherData };
                        } else {
                            STATE.users[idx] = { ...STATE.users[idx], ...data };
                        }
                    }
                });
                if (typeof renderUsersTable === 'function') renderUsersTable();
                if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
            }, err => console.warn('Aviso en onSnapshot docentes:', err));
            if (typeof unsubDocentes === 'function') _firestoreModularUnsubscribers.push(unsubDocentes);
        } catch(e) {}

        // 2. 📝 ESCUCHAR CALIFICACIONES Y ESTUDIANTES ('students') EN TIEMPO REAL (FUSIÓN PROFUNDA POR MATERIA)
        try {
            const unsubStudents = onSnapshot(collection(db, 'students'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales

                snap.docChanges().forEach(change => {
                    const sData = change.doc.data();
                    const sId = change.doc.id;
                    const fullStudent = { id: sId, ...sData };

                    const idx = (STATE.students || []).findIndex(s => s.id === sId);
                    if (change.type === 'added' || change.type === 'modified') {
                        if (idx !== -1) {
                            // Fusión profunda y aislada por materia y unidad para no sobreescribir materias entre docentes
                            const existingGrades = STATE.students[idx].grades || {};
                            const newGrades = fullStudent.grades || {};
                            const mergedGrades = { ...existingGrades, ...newGrades };

                            const existingDetails = STATE.students[idx].gradebookDetails || {};
                            const newDetails = fullStudent.gradebookDetails || {};
                            const mergedDetails = { ...existingDetails };
                            Object.keys(newDetails).forEach(subj => {
                                mergedDetails[subj] = {
                                    ...(mergedDetails[subj] || {}),
                                    ...(newDetails[subj] || {})
                                };
                            });

                            STATE.students[idx] = {
                                ...STATE.students[idx],
                                ...fullStudent,
                                grades: mergedGrades,
                                gradebookDetails: mergedDetails
                            };
                        } else {
                            if (!STATE.students) STATE.students = [];
                            STATE.students.push(fullStudent);
                        }
                    } else if (change.type === 'removed') {
                        if (idx !== -1) STATE.students.splice(idx, 1);
                    }
                });

                // Actualizar interfaz reactiva en tiempo real sin recargar página
                if (typeof renderGradebookTable === 'function') renderGradebookTable();
                if (typeof loadTeacherGradebook === 'function' && STATE.activeView === 'gradebook') loadTeacherGradebook();
                if (typeof renderStudentsTable === 'function') renderStudentsTable();
                if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
            }, err => console.warn('Aviso en onSnapshot students:', err));
            if (typeof unsubStudents === 'function') _firestoreModularUnsubscribers.push(unsubStudents);
        } catch(e) {}

        // 3. 🛡️ ESCUCHAR ROLES Y PERMISOS ('rolesConfig') EN TIEMPO REAL
        try {
            const unsubRoles = onSnapshot(collection(db, 'rolesConfig'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales
                const roles = [];
                snap.forEach(d => roles.push({ key: d.id, ...d.data() }));
                if (roles.length > 0) {
                    STATE.rolesConfig = roles;
                    if (typeof renderRolesTable === 'function') renderRolesTable();
                    if (typeof renderRoleSelectorTabs === 'function') renderRoleSelectorTabs();
                    if (typeof updateUserRoleSelectOptions === 'function') updateUserRoleSelectOptions();
                    if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole);
                }
            }, err => console.warn('Aviso en onSnapshot rolesConfig:', err));
            if (typeof unsubRoles === 'function') _firestoreModularUnsubscribers.push(unsubRoles);
        } catch(e) {}

        // Escuchar documento de configuración de roles
        try {
            const unsubRolesDoc = onSnapshot(doc(db, 'config', 'rolesConfig'), (snap) => {
                if (!snap || !snap.exists()) return;
                // Snapshot listener activo sin bloqueos locales
                const d = snap.data();
                if (d && Array.isArray(d.roles)) {
                    STATE.rolesConfig = d.roles;
                    if (typeof renderRolesTable === 'function') renderRolesTable();
                    if (typeof renderRoleSelectorTabs === 'function') renderRoleSelectorTabs();
                    if (typeof updateUserRoleSelectOptions === 'function') updateUserRoleSelectOptions();
                    if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole);
                }
            }, err => console.warn('Aviso en onSnapshot config/rolesConfig:', err));
            if (typeof unsubRolesDoc === 'function') _firestoreModularUnsubscribers.push(unsubRolesDoc);
        } catch(e) {}

        // 4. 🎓 ESCUCHAR MAESTROS GUÍAS Y GRADOS ('gradesList' y subcolección 'grados_secciones') EN TIEMPO REAL
        try {
            const unsubGrades = onSnapshot(collection(db, 'gradesList'), (snap) => {
                if (!snap || snap.empty) return;
                if (!Array.isArray(STATE.gradesList) || STATE.gradesList.length < 12) {
                    if (typeof ensureOfficialGradesList === 'function') ensureOfficialGradesList();
                }
                snap.forEach(d => {
                    const gData = { id: d.id, ...d.data() };
                    const idx = (STATE.gradesList || []).findIndex(g => g && (g.id === d.id || g.code === d.id));
                    if (idx !== -1) {
                        STATE.gradesList[idx] = { ...STATE.gradesList[idx], ...gData };
                    } else {
                        STATE.gradesList.push(gData);
                    }
                });
                if (typeof ensureOfficialGradesList === 'function') ensureOfficialGradesList();
                if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                if (typeof renderGradesTable === 'function') renderGradesTable();
                if (typeof updateGradeSelects === 'function') updateGradeSelects();
                if (typeof renderCurrentView === 'function' && (STATE.activeView === 'grades' || STATE.activeView === 'guide-teachers')) renderCurrentView();
            }, err => console.warn('Aviso en onSnapshot gradesList:', err));

            // Sincronizar también entidad 'secciones' en tiempo real
            try {
                const unsubSecciones = onSnapshot(collection(db, 'secciones'), (secSnap) => {
                    if (!secSnap || secSnap.empty) return;
                    secSnap.forEach(d => {
                        const sec = d.data();
                        if (!sec) return;
                        const docId = d.id;
                        const gMatch = (STATE.gradesList || []).find(g => 
                            g && (g.id === sec.id || g.code === sec.codigo ||
                            (docId && docId.includes('_') && g.code && g.code.includes(docId.split('_')[0]) && g.code.includes(docId.split('_')[1])))
                        );
                        if (gMatch) {
                            if (sec.maestroGuiaId) gMatch.guideTeacherId = sec.maestroGuiaId;
                            if (sec.maestroGuiaNombre) gMatch.guideTeacher = sec.maestroGuiaNombre;
                        }
                    });
                    if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                    if (typeof renderGradesTable === 'function') renderGradesTable();
                }, err => console.warn('Aviso en onSnapshot secciones:', err));
                if (typeof unsubSecciones === 'function') _firestoreModularUnsubscribers.push(unsubSecciones);
            } catch(eSec) {}
            if (typeof unsubGrades === 'function') _firestoreModularUnsubscribers.push(unsubGrades);
        } catch(e) {}

        // 4b. 🏫 ESCUCHAR ENTIDAD DEDICADA 'grados_secciones' EN TIEMPO REAL
        try {
            const unsubSections = onSnapshot(collection(db, 'grados_secciones'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales
                snap.docChanges().forEach(change => {
                    const data = change.doc.data();
                    const gId = change.doc.id;
                    const fullObj = { id: gId, ...data };
                    const idx = (STATE.gradesList || []).findIndex(g => g.id === gId || g.code === gId);
                    if (change.type === 'added' || change.type === 'modified') {
                        if (idx !== -1) {
                            STATE.gradesList[idx] = { ...STATE.gradesList[idx], ...fullObj };
                        } else {
                            if (!STATE.gradesList) STATE.gradesList = [];
                            STATE.gradesList.push(fullObj);
                        }
                    } else if (change.type === 'removed' && idx !== -1) {
                        STATE.gradesList.splice(idx, 1);
                    }
                });
                if (typeof renderGradesTable === 'function') renderGradesTable();
                if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
            }, err => console.warn('Aviso en onSnapshot grados_secciones:', err));
            if (typeof unsubSections === 'function') _firestoreModularUnsubscribers.push(unsubSections);
        } catch(e) {}

        // 4c. 👨‍🏫 ESCUCHAR ENTIDAD DEDICADA 'maestros_guias' EN TIEMPO REAL
        try {
            const unsubGuides = onSnapshot(collection(db, 'maestros_guias'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales
                snap.forEach(d => {
                    const data = d.data();
                    const gId = data.gradeId || d.id;
                    const gradeObj = (STATE.gradesList || []).find(g => g.id === gId || g.code === gId);
                    if (gradeObj && data.guideTeacherId !== undefined) {
                        gradeObj.guideTeacherId = data.guideTeacherId;
                        gradeObj.guideTeacher = data.guideTeacher || 'Sin asignar';
                    }
                });
                if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
                if (typeof renderGradesTable === 'function') renderGradesTable();
            }, err => console.warn('Aviso en onSnapshot maestros_guias:', err));
            if (typeof unsubGuides === 'function') _firestoreModularUnsubscribers.push(unsubGuides);
        } catch(e) {}

        // 4d. 🔒 ESCUCHAR 'config/bimestre_activo', 'configuracion_sistema/global' Y 'config/control_bloqueo' EN TIEMPO REAL
        try {
            const handleBimestreChange = (d) => {
                const bNum = parseInt(d.activeBimestre || d.bimestreActivoOficial);
                if (bNum && bNum >= 1 && bNum <= 4) {
                    if (!STATE.config) STATE.config = {};
                    const prevBim = STATE.config.activeBimestre;
                    STATE.config.activeBimestre = bNum;
                    STATE.config.bimestreActivoOficial = bNum;
                    const headerBadge = document.getElementById('headerPreviewBimestreBadge');
                    if (headerBadge) headerBadge.textContent = `${bNum}º Bimestre Activo`;
                    const officialSelect = document.getElementById('officialActiveBimestreSelect');
                    if (officialSelect && parseInt(officialSelect.value) !== bNum) officialSelect.value = String(bNum);
                    if (Array.isArray(d.activeUnits) && d.activeUnits.length > 0) {
                        STATE.config.activeUnits = d.activeUnits.map(Number);
                    }
                    [1, 2, 3, 4].forEach(u => {
                        const chk = document.getElementById('checkActiveUnit' + u);
                        if (chk) chk.checked = (STATE.config.activeUnits || [bNum]).includes(u);
                    });
                    if (typeof populateGradebookBimestreSelect === 'function') populateGradebookBimestreSelect();
                    // ⚡ Reflejo instantáneo para los catedráticos sin recargar la página
                    if (STATE.activeView === 'gradebook' && typeof renderGradebookTable === 'function') {
                        const gSelect = document.getElementById('gradebookBimestreSelect');
                        if (gSelect && (!gSelect.value || parseInt(gSelect.value) === prevBim)) {
                            gSelect.value = String(bNum);
                        }
                        renderGradebookTable();
                    }
                }
            };

            const handleLockChange = (d) => {
                if (d.globalLocked !== undefined) {
                    if (!STATE.config) STATE.config = {};
                    STATE.config.globalLocked = !!d.globalLocked;
                    if (d.teacherBypass && typeof d.teacherBypass === 'object') {
                        STATE.config.teacherBypass = { ...(STATE.config.teacherBypass || {}), ...d.teacherBypass };
                    }
                    const badge = document.getElementById('globalLockBadge');
                    if (badge) {
                        badge.className = STATE.config.globalLocked ? 'badge badge-danger' : 'badge badge-success';
                        badge.textContent = STATE.config.globalLocked ? 'Bloqueado General' : 'Habilitado General';
                    }
                    if (typeof loadLockStatus === 'function' && STATE.activeView === 'grade-lock') {
                        loadLockStatus();
                    }
                    // ⚡ Actualización inmediata del libro de calificaciones de catedráticos
                    if (STATE.activeView === 'gradebook' && typeof renderGradebookTable === 'function') {
                        renderGradebookTable();
                    }
                }
            };

            const unsubBim = onSnapshot(doc(db, 'config', 'bimestre_activo'), (snap) => {
                if (!snap || !snap.exists()) return;
                // Snapshot listener activo sin bloqueos locales
                handleBimestreChange(snap.data());
            }, err => console.warn('Aviso en onSnapshot config/bimestre_activo:', err));
            if (typeof unsubBim === 'function') _firestoreModularUnsubscribers.push(unsubBim);

            const unsubSysGlobal = onSnapshot(doc(db, 'configuracion_sistema', 'global'), (snap) => {
                if (!snap || !snap.exists()) return;
                // Snapshot listener activo sin bloqueos locales
                const data = snap.data();
                if (data.activeBimestre !== undefined || data.bimestreActivoOficial !== undefined) handleBimestreChange(data);
                if (data.globalLocked !== undefined) handleLockChange(data);
            }, err => console.warn('Aviso en onSnapshot configuracion_sistema/global:', err));
            if (typeof unsubSysGlobal === 'function') _firestoreModularUnsubscribers.push(unsubSysGlobal);

            const unsubConfigSistema = onSnapshot(doc(db, 'configuracion', 'sistema'), (snap) => {
                if (!snap || !snap.exists()) return;
                const data = snap.data();
                if (data.activeBimestre !== undefined || data.bimestreActivoOficial !== undefined) handleBimestreChange(data);
                if (data.globalLocked !== undefined) handleLockChange(data);
            }, err => console.warn('Aviso en onSnapshot configuracion/sistema:', err));
            if (typeof unsubConfigSistema === 'function') _firestoreModularUnsubscribers.push(unsubConfigSistema);

            const unsubConfigBimAct = onSnapshot(doc(db, 'configuracion', 'bimestreActivo'), (snap) => {
                if (!snap || !snap.exists()) return;
                handleBimestreChange(snap.data());
            }, err => console.warn('Aviso en onSnapshot configuracion/bimestreActivo:', err));
            if (typeof unsubConfigBimAct === 'function') _firestoreModularUnsubscribers.push(unsubConfigBimAct);

            const unsubLock = onSnapshot(doc(db, 'config', 'control_bloqueo'), (snap) => {
                if (!snap || !snap.exists()) return;
                // Snapshot listener activo sin bloqueos locales
                handleLockChange(snap.data());
            }, err => console.warn('Aviso en onSnapshot config/control_bloqueo:', err));
            if (typeof unsubLock === 'function') _firestoreModularUnsubscribers.push(unsubLock);
        } catch(e) {}

        // 5. 📚 ESCUCHAR ASIGNACIONES DE CÁTEDRAS ('pensum' y 'clases')
        try {
            const rutaColeccion = 'pensum';
            console.log("Consultando asignaciones en ruta:", rutaColeccion);
            const unsubPensum = onSnapshot(collection(db, rutaColeccion), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales
                const items = [];
                snap.forEach(d => items.push({ id: d.id, ...d.data() }));
                if (items.length >= (STATE.pensum || []).length && items.length > 0) {
                    STATE.pensum = items;
                } else if (items.length > 0) {
                    // Fusión inteligente para preservar nómina autoritativa de 112 cátedras
                    const currentMap = new Map((STATE.pensum || []).map(p => [p.id, p]));
                    items.forEach(item => currentMap.set(item.id, { ...(currentMap.get(item.id) || {}), ...item }));
                    STATE.pensum = Array.from(currentMap.values());
                }
                if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
                if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
                if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();
            }, err => console.warn('Aviso en onSnapshot pensum:', err));
            if (typeof unsubPensum === 'function') _firestoreModularUnsubscribers.push(unsubPensum);
        } catch(e) {}

        // 6. 📖 ESCUCHAR CATÁLOGO DE ASIGNATURAS ('pensumCatalog')
        try {
            const unsubPensumCat = onSnapshot(collection(db, 'pensumCatalog'), (snap) => {
                if (!snap || snap.empty) return;
                // Snapshot listener activo sin bloqueos locales
                const items = [];
                snap.forEach(d => items.push({ id: d.id, ...d.data() }));
                if (items.length > 0) {
                    STATE.pensumCatalog = items;
                    if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
                    if (typeof updatePensumCatalogSelects === 'function') updatePensumCatalogSelects();
                    if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();
                    if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
                }
            }, err => console.warn('Aviso en onSnapshot pensumCatalog:', err));
            if (typeof unsubPensumCat === 'function') _firestoreModularUnsubscribers.push(unsubPensumCat);
        } catch(e) {}
    } catch(err) {
        console.warn('Aviso al configurar Firestore onSnapshot:', err);
    }
}

function unsubscribeAllFirestoreListeners() {
    if (typeof _firestoreModularUnsubscribers !== 'undefined' && Array.isArray(_firestoreModularUnsubscribers) && _firestoreModularUnsubscribers.length > 0) {
        console.log(`🔌 [Firestore] Desuscribiendo ${_firestoreModularUnsubscribers.length} listeners en tiempo real para liberar sockets...`);
        _firestoreModularUnsubscribers.forEach(unsub => {
            try { if (typeof unsub === 'function') unsub(); } catch(e) {}
        });
        _firestoreModularUnsubscribers = [];
    }
}

// ⏱️ Vigilante de inactividad de 5 minutos (desuscripción automática para evitar fugas de memoria y sobreescrituras en background)
let _enccoInactivityTimer = null;
function handleEnccoUserActivity() {
    if (_enccoInactivityTimer) clearTimeout(_enccoInactivityTimer);
    // Si los listeners fueron desuscritos por inactividad y el usuario regresa, reactivarlos
    if (typeof _firestoreModularUnsubscribers !== 'undefined' && _firestoreModularUnsubscribers.length === 0 &&
        window.FirebaseModular && window.FirebaseModular.db && STATE && STATE.currentUser) {
        console.log("⚡ [Firestore] Actividad detectada tras inactividad: reactivando listeners en tiempo real...");
        initFirestoreModularLiveListeners();
    }
    _enccoInactivityTimer = setTimeout(() => {
        console.log("💤 [Firestore] 5 minutos de inactividad detectados. Desuscribiendo listeners en segundo plano para optimizar rendimiento...");
        unsubscribeAllFirestoreListeners();
        if (typeof unsubscribeCurrentGradebookListener === 'function') {
            unsubscribeCurrentGradebookListener();
        }
    }, 5 * 60 * 1000);
}

if (typeof window !== 'undefined') {
    window.initFirestoreModularLiveListeners = initFirestoreModularLiveListeners;
    window.unsubscribeAllFirestoreListeners = unsubscribeAllFirestoreListeners;
    window.addEventListener('FirebaseModularReady', initFirestoreModularLiveListeners);

    ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'].forEach(evt => {
        window.addEventListener(evt, handleEnccoUserActivity, { passive: true });
    });
    handleEnccoUserActivity();

    if (window.FirebaseModular && window.FirebaseModular.db) {
        initFirestoreModularLiveListeners();
    }
}

// ==============================================================================
// 🌐 DIAGNÓSTICO DE RED, LIMPIEZA DE LISTENERS Y LIBERACIÓN DE RECURSOS
// ==============================================================================
async function diagnosticoRedFirebase() {
    console.log("🔍 [Diagnóstico de Red] Iniciando auditoría de conectividad y sockets...");
    const report = {
        timestamp: new Date().toISOString(),
        online: typeof navigator !== "undefined" ? navigator.onLine : true,
        rtdbUrl: typeof getFirebaseDatabaseUrl === "function" ? getFirebaseDatabaseUrl() : "N/A",
        rtdbLatencyMs: null,
        rtdbStatus: "pending",
        firestoreActiveListeners: (typeof _firestoreModularUnsubscribers !== "undefined") ? _firestoreModularUnsubscribers.length : 0,
        firestoreReady: !!(typeof window !== "undefined" && window.FirebaseModular && window.FirebaseModular.db),
        eventSourceConnected: !!(typeof _firebaseEventSource !== "undefined" && _firebaseEventSource && _firebaseEventSource.readyState === 1)
    };
    const startRtdb = Date.now();
    try {
        const controller = (typeof AbortController !== "undefined") ? new AbortController() : null;
        const timeoutId = controller ? setTimeout(() => controller.abort(), 4000) : null;
        const res = await fetch(`${report.rtdbUrl}/encc_school_state/lastModified.json`, {
            signal: controller ? controller.signal : undefined
        });
        if (timeoutId) clearTimeout(timeoutId);
        report.rtdbLatencyMs = Date.now() - startRtdb;
        report.rtdbStatus = res.ok ? "Optimo (200 OK)" : `HTTP ${res.status}`;
    } catch(err) {
        report.rtdbLatencyMs = Date.now() - startRtdb;
        report.rtdbStatus = err.name === "AbortError" ? "TIMEOUT (>4000ms)" : err.message;
    }
    if (typeof console.table === "function") {
        console.table(report);
    } else {
        console.log("Reporte de Diagnostico:", report);
    }
    return report;
}

function limpiarListenersFirebase() {
    console.log("🧹 [Limpieza de Sockets] Desuscribiendo listeners activos para descongestionar el canal de red...");
    let count = 0;
    if (typeof unsubscribeAllFirestoreListeners === "function") {
        count += (typeof _firestoreModularUnsubscribers !== "undefined" && Array.isArray(_firestoreModularUnsubscribers)) ? _firestoreModularUnsubscribers.length : 0;
        unsubscribeAllFirestoreListeners();
    }
    if (typeof _firebaseEventSource !== "undefined" && _firebaseEventSource) {
        try {
            _firebaseEventSource.close();
            _firebaseEventSource = null;
            count++;
            console.log("EventSource SSE cerrado.");
        } catch(e) {}
    }
    console.log(`✅ [Limpieza de Sockets] Se cerraron ${count} conexiones y listeners concurrentes.`);
    return count;
}

if (typeof window !== "undefined") {
    window.diagnosticoRedFirebase = diagnosticoRedFirebase;
    window.limpiarListenersFirebase = limpiarListenersFirebase;
}

// ==============================================================================
// 🧪 PRUEBA DE ESCRITURA INMEDIATA EN FIRESTORE Y REALTIME DATABASE
// ==============================================================================
async function probarEscrituraFirestore() {
    console.log("🧪 [Prueba de Escritura Inmediata] Iniciando test en Firestore y RTDB...");
    const results = {
        timestamp: new Date().toISOString(),
        realtimeDatabase: { status: "pending", latencyMs: null, error: null },
        firestore: { status: "pending", latencyMs: null, error: null }
    };
    // 1. Probar Realtime Database
    const startRtdb = Date.now();
    try {
        const firebaseUrl = (typeof getFirebaseDatabaseUrl === "function") ? getFirebaseDatabaseUrl() : "https://encco-jutiapa-live-2026-default-rtdb.firebaseio.com";
        const controller = (typeof AbortController !== "undefined") ? new AbortController() : null;
        const timeoutId = controller ? setTimeout(() => controller.abort(), 4000) : null;
        const res = await fetch(`${firebaseUrl}/encc_school_state/config.json`, {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ pingTestAt: new Date().toISOString() }),
            signal: controller ? controller.signal : undefined
        });
        if (timeoutId) clearTimeout(timeoutId);
        results.realtimeDatabase.latencyMs = Date.now() - startRtdb;
        results.realtimeDatabase.status = res.ok ? `EXITO (HTTP ${res.status})` : `Error HTTP ${res.status}`;
    } catch(rtdbErr) {
        results.realtimeDatabase.latencyMs = Date.now() - startRtdb;
        results.realtimeDatabase.status = "Fallo";
        results.realtimeDatabase.error = rtdbErr.message;
    }
    // 2. Probar Cloud Firestore
    const startFs = Date.now();
    if (window.FirebaseModular && window.FirebaseModular.db && typeof window.FirebaseModular.setDoc === "function") {
        const { db, doc, setDoc } = window.FirebaseModular;
        const testRef = doc(db, "configuracion", "sistema");
        const timeoutFs = new Promise((_, reject) => 
            setTimeout(() => reject(new Error("Tiempo de espera agotado (>4000ms).")), 4000)
        );
        try {
            await Promise.race([
                setDoc(testRef, { 
                    ultimaPruebaEscritura: new Date().toISOString(),
                    testWritePing: true
                }, { merge: true }),
                timeoutFs
            ]);
            results.firestore.latencyMs = Date.now() - startFs;
            results.firestore.status = "EXITO (setDoc confirmado en configuracion/sistema)";
        } catch(fsErr) {
            results.firestore.latencyMs = Date.now() - startFs;
            results.firestore.status = "Tiempo de espera / Error";
            results.firestore.error = fsErr.message;
        }
    } else {
        results.firestore.status = "SDK Firestore no inicializado en memoria";
    }
    if (typeof console.table === "function") {
        console.table(results);
    } else {
        console.log("Resultados de prueba de escritura:", results);
    }
    return results;
}

if (typeof window !== "undefined") {
    window.probarEscrituraFirestore = probarEscrituraFirestore;
}

// ==============================================================================
// 🛡️ DELEGACIÓN UNIVERSAL DE EVENTOS DE GUARDADO (GLOBAL SAVE DISPATCHER)
// ==============================================================================
let _globalSaveDelegationInitialized = false;
function initGlobalSaveDelegation() {
    if (typeof document === 'undefined') return;
    if (_globalSaveDelegationInitialized) return;
    _globalSaveDelegationInitialized = true;

    // A. Interceptación delegada de envíos de formularios (submit por botón o Enter)
    document.addEventListener('submit', async function (e) {
        const form = e.target;
        if (!form || !form.tagName || form.tagName.toUpperCase() !== 'FORM') return;

        if (e._enccoHandled) return;

        let saveHandler = null;
        let handlerName = '';

        if (form.id === 'mainEnrollmentForm' || (form.closest && form.closest('#enrollmentModal'))) {
            saveHandler = window.saveStudentForm;
            handlerName = 'saveStudentForm';
        } else if (form.id === 'userModalMainForm' || (form.closest && form.closest('#userModal'))) {
            saveHandler = window.submitUserForm || window.saveUserForm;
            handlerName = 'submitUserForm';
        } else if (form.id === 'pensumSubjectForm' || (form.closest && form.closest('#pensumSubjectModal'))) {
            saveHandler = window.savePensumSubjectForm;
            handlerName = 'savePensumSubjectForm';
        } else if (form.closest && form.closest('#classAssignmentModal')) {
            saveHandler = window.saveClassAssignmentForm;
            handlerName = 'saveClassAssignmentForm';
        } else if (form.closest && (form.closest('#gradeModal') || form.closest('#gradebookEntryModal'))) {
            saveHandler = window.saveGradeForm;
            handlerName = 'saveGradeForm';
        } else if (form.closest && form.closest('#assignGuideTeacherModal')) {
            saveHandler = window.saveQuickGuideTeacher;
            handlerName = 'saveQuickGuideTeacher';
        } else if (form.closest && form.closest('#gradingConfigModal')) {
            saveHandler = window.saveGradingConfigForm;
            handlerName = 'saveGradingConfigForm';
        } else if (form.closest && form.closest('#careerModal')) {
            saveHandler = window.saveCareerForm;
            handlerName = 'saveCareerForm';
        } else if (form.closest && form.closest('#cycleModal')) {
            saveHandler = window.saveCycleForm;
            handlerName = 'saveCycleForm';
        } else if (form.closest && form.closest('#studentProfileModal')) {
            saveHandler = window.saveStudentProfileForm;
            handlerName = 'saveStudentProfileForm';
        } else if (form.id === 'academicExonerationForm' || (form.closest && form.closest('#academicExonerationModal'))) {
            saveHandler = window.saveAcademicExoneration;
            handlerName = 'saveAcademicExoneration';
        } else if (form.closest && form.closest('#disciplineModal')) {
            saveHandler = window.saveDisciplineForm;
            handlerName = 'saveDisciplineForm';
        } else if (form.closest && form.closest('#disciplineResolutionModal')) {
            saveHandler = window.saveDisciplineResolutionForm;
            handlerName = 'saveDisciplineResolutionForm';
        } else if (form.id === 'roleForm' || (form.closest && form.closest('#roleModal'))) {
            saveHandler = window.saveRoleForm;
            handlerName = 'saveRoleForm';
        } else if (form.id === 'formGradeEditRequest' || (form.closest && form.closest('#modalGradeEditRequest'))) {
            saveHandler = window.submitGradeEditRequest;
            handlerName = 'submitGradeEditRequest';
        } else if (form.closest && form.closest('#forgotPasswordModal')) {
            saveHandler = window.handlePasswordRecovery;
            handlerName = 'handlePasswordRecovery';
        }

        if (typeof saveHandler === 'function') {
            e.preventDefault();
            if (e.stopPropagation) e.stopPropagation();
            e._enccoHandled = true;
            try {
                await saveHandler(e);
            } catch (err) {
                console.error(`❌ [Global Save Dispatcher] Error al procesar ${handlerName}:`, err);
            }
        }
    }, false);

    // B. Interceptación delegada de clics en botones de guardado (type="button", toolbars o tablas dinámicas)
    document.addEventListener('click', async function (e) {
        const btn = e.target ? (e.target.closest ? e.target.closest('button, .btn-save-trigger, input[type="submit"]') : null) : null;
        if (!btn) return;

        if (btn.disabled || (btn.innerHTML && btn.innerHTML.includes('fa-spin'))) {
            e.preventDefault();
            return;
        }

        if (e._enccoHandled) return;

        let saveHandler = null;
        let handlerName = '';
        const btnOnclick = btn.getAttribute('onclick') || '';

        if (btn.id === 'userFormSubmitBtn' || btnOnclick.includes('submitUserForm') || btnOnclick.includes('saveUserForm')) {
            saveHandler = window.submitUserForm || window.saveUserForm;
            handlerName = 'submitUserForm';
        } else if (btn.id === 'enrollmentSubmitTopBtn' || btn.id === 'enrollmentSubmitBottomBtn' || (btnOnclick.includes('saveStudentForm') && !btnOnclick.includes('saveStudentProfileForm'))) {
            saveHandler = window.saveStudentForm;
            handlerName = 'saveStudentForm';
        } else if (btnOnclick.includes('saveGradebookChanges')) {
            saveHandler = window.saveGradebookChanges;
            handlerName = 'saveGradebookChanges';
        } else if (btnOnclick.includes('saveAttendanceRecords')) {
            saveHandler = window.saveAttendanceRecords;
            handlerName = 'saveAttendanceRecords';
        } else if (btnOnclick.includes('saveActiveRolePermissions')) {
            saveHandler = window.saveActiveRolePermissions;
            handlerName = 'saveActiveRolePermissions';
        } else if (btnOnclick.includes('saveFirebaseDatabaseConfig')) {
            saveHandler = window.saveFirebaseDatabaseConfig;
            handlerName = 'saveFirebaseDatabaseConfig';
        } else if (btnOnclick.includes('saveSchoolHeaderConfig')) {
            saveHandler = window.saveSchoolHeaderConfig;
            handlerName = 'saveSchoolHeaderConfig';
        }

        if (typeof saveHandler === 'function') {
            e.preventDefault();
            if (e.stopPropagation) e.stopPropagation();
            e._enccoHandled = true;
            try {
                await saveHandler(e);
            } catch (err) {
                console.error(`❌ [Global Save Dispatcher] Error al procesar clic en ${handlerName}:`, err);
            }
        }
    }, false);
}

// Exportación universal en window para garantizar resolución en cualquier contexto
if (typeof window !== 'undefined') {
    window.submitUserForm = submitUserForm;
    window.saveUserForm = saveUserForm;
    window.savePensumSubjectForm = savePensumSubjectForm;
    window.saveClassAssignmentForm = saveClassAssignmentForm;
    window.saveGradeForm = saveGradeForm;
    window.saveGradebookChanges = saveGradebookChanges;
    window.saveQuickGuideTeacher = saveQuickGuideTeacher;
    window.saveCareerForm = saveCareerForm;
    window.saveCycleForm = saveCycleForm;
    window.saveGradingConfigForm = saveGradingConfigForm;
    window.submitGradeEditRequest = submitGradeEditRequest;
    window.saveAcademicExoneration = saveAcademicExoneration;
    window.saveDisciplineForm = saveDisciplineForm;
    window.saveDisciplineResolutionForm = saveDisciplineResolutionForm;
    window.saveStudentForm = saveStudentForm;
    window.saveStudentProfileForm = saveStudentProfileForm;
    window.saveRoleForm = saveRoleForm;
    window.saveActiveRolePermissions = saveActiveRolePermissions;
    window.saveAttendanceRecords = saveAttendanceRecords;
    window.saveSchoolHeaderConfig = saveSchoolHeaderConfig;
    window.saveFirebaseDatabaseConfig = saveFirebaseDatabaseConfig;
    window.handlePasswordRecovery = handlePasswordRecovery;
    window.initGlobalSaveDelegation = initGlobalSaveDelegation;

    if (typeof document !== 'undefined') {
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initGlobalSaveDelegation);
        } else {
            initGlobalSaveDelegation();
        }
    }
}
